// Os 90 textos da fase 1 (dias 1 a 90).
const DAYS = [
{ d: 1, title: `About me`, pt: `Sobre mim`, lvl: 'A1',
  en: [`Hi! My name is Lucas. I'm twenty-eight years old and I'm from Brazil. I live in a small apartment with my brother.`,
       `I work in an office, and I'm learning English because I need it for my job. I also want to travel and watch movies without subtitles.`,
       `I'm not fluent yet, but I study a little every day. I like music, coffee and soccer. I don't like waking up early, but I do it anyway.`,
       `Nice to meet you!`],
  tr: [`Oi! Meu nome é Lucas. Tenho vinte e oito anos e sou do Brasil. Moro num apartamento pequeno com meu irmão.`,
       `Trabalho num escritório e estou aprendendo inglês porque preciso dele para o meu trabalho. Também quero viajar e assistir filmes sem legenda.`,
       `Ainda não sou fluente, mas estudo um pouco todo dia. Gosto de música, café e futebol. Não gosto de acordar cedo, mas faço isso mesmo assim.`,
       `Prazer em te conhecer!`],
  chunks: [[`I'm from`, `eu sou de`], [`I live in`, `eu moro em`], [`I'm learning English`, `estou aprendendo inglês`], [`I need it for my job`, `preciso disso para o meu trabalho`], [`I'm not fluent yet`, `ainda não sou fluente`], [`I do it anyway`, `faço mesmo assim`]],
  focus: `Idade em inglês usa o verbo to be: “I'm twenty-eight”, nunca “I have 28 years”.`,
  tasks: [`Reescreva o texto com os seus dados e leia em voz alta.`, `Diga 3 coisas que você gosta e 1 que não gosta: “I like… I don't like…”.`] },

{ d: 2, title: `My morning`, pt: `Minha manhã`, lvl: 'A1',
  en: [`I usually wake up at six thirty. I check my phone, and then I get up. I take a quick shower and get dressed.`,
       `For breakfast, I have coffee and bread with butter. I don't have much time, so I eat fast.`,
       `At seven fifteen, I leave home and take the bus to work. The bus is always full. I listen to a podcast in English on the way. It helps me a lot.`,
       `I get to work at eight o'clock.`],
  tr: [`Eu normalmente acordo às seis e meia. Olho o celular e depois levanto. Tomo um banho rápido e me visto.`,
       `No café da manhã, tomo café e como pão com manteiga. Não tenho muito tempo, então como rápido.`,
       `Às sete e quinze, saio de casa e pego o ônibus para o trabalho. O ônibus está sempre cheio. Escuto um podcast em inglês no caminho. Isso me ajuda muito.`,
       `Chego no trabalho às oito horas.`],
  chunks: [[`wake up`, `acordar`], [`get up`, `levantar (da cama)`], [`take a quick shower`, `tomar um banho rápido`], [`get dressed`, `se vestir`], [`leave home`, `sair de casa`], [`on the way`, `no caminho`], [`It helps me a lot`, `isso me ajuda muito`], [`get to work`, `chegar no trabalho`]],
  focus: `“Wake up” é abrir os olhos. “Get up” é sair da cama. Nativos usam os dois o tempo todo.`,
  tasks: [`Conte a sua manhã de hoje usando pelo menos 5 expressões marcadas.`, `Que horas você acorda e sai de casa? Responda em voz alta.`] },

{ d: 3, title: `At work`, pt: `No trabalho`, lvl: 'A1',
  en: [`I work in a big company. In the morning, I answer emails and check my tasks for the day.`,
       `Today I'm really busy. I have a meeting at ten and I have to finish a report before lunch.`,
       `My boss is nice, but she asks a lot of questions. When I don't know the answer, I say, “Let me check and get back to you.”`,
       `I have lunch at noon with my coworkers. We talk about work, food and soccer. In the afternoon, I try to focus and finish everything on time.`],
  tr: [`Trabalho numa empresa grande. De manhã, respondo e-mails e confiro minhas tarefas do dia.`,
       `Hoje estou muito ocupado. Tenho uma reunião às dez e preciso terminar um relatório antes do almoço.`,
       `Minha chefe é legal, mas ela faz muitas perguntas. Quando não sei a resposta, eu digo: “Deixa eu verificar e te retorno.”`,
       `Almoço ao meio-dia com meus colegas de trabalho. Falamos de trabalho, comida e futebol. À tarde, tento me concentrar e terminar tudo no prazo.`],
  chunks: [[`I'm really busy`, `estou muito ocupado`], [`I have to finish`, `eu preciso terminar`], [`before lunch`, `antes do almoço`], [`Let me check and get back to you`, `deixa eu verificar e te retorno`], [`coworkers`, `colegas de trabalho`], [`on time`, `no prazo / na hora`]],
  focus: `“I have to” = preciso / tenho que. É uma das estruturas mais usadas do inglês: I have to go, I have to work, I have to study.`,
  tasks: [`Diga 3 coisas que você tem que fazer hoje: “Today I have to…”.`, `Use “Let me check and get back to you” respondendo a uma pergunta imaginária do seu chefe.`] },

{ d: 4, title: `After work`, pt: `Depois do trabalho`, lvl: 'A1',
  en: [`I usually get home at around six. I'm always tired, but I feel better after a shower.`,
       `I don't like cooking, so I make something simple, like rice, eggs and salad. Sometimes I order food, but it's expensive.`,
       `After dinner, I watch a series in English. I use English subtitles, and I pause when I hear a new word.`,
       `I go to bed at eleven. Before I sleep, I review my words for five minutes. It's a small habit, but it works.`],
  tr: [`Normalmente chego em casa por volta das seis. Estou sempre cansado, mas me sinto melhor depois de um banho.`,
       `Não gosto de cozinhar, então faço algo simples, tipo arroz, ovos e salada. Às vezes peço comida, mas é caro.`,
       `Depois do jantar, assisto uma série em inglês. Uso legenda em inglês e pauso quando ouço uma palavra nova.`,
       `Vou dormir às onze. Antes de dormir, reviso minhas palavras por cinco minutos. É um hábito pequeno, mas funciona.`],
  chunks: [[`get home`, `chegar em casa`], [`at around six`, `por volta das seis`], [`I feel better`, `me sinto melhor`], [`something simple`, `algo simples`], [`order food`, `pedir comida`], [`go to bed`, `ir dormir`], [`it works`, `funciona`]],
  focus: `“Get home” não leva “to”: I get home, I go home. Mas “I go to work”, “I go to bed”.`,
  tasks: [`Conte o que você fez ontem à noite depois do trabalho ou da faculdade (pode usar o presente por enquanto).`, `Qual é o seu pequeno hábito que funciona? “It's a small habit, but…”.`] },

{ d: 5, title: `How's it going?`, pt: `E aí, tudo bem?`, lvl: 'A1',
  en: [`Anna: Hey, Mark! How's it going?`, `Mark: Pretty good, thanks. How about you?`, `Anna: Not bad. A little tired. It's been a long week.`,
       `Mark: I know what you mean. Any plans for the weekend?`, `Anna: Nothing special. Maybe I'll just stay home and relax. What about you?`,
       `Mark: I'm going to see my parents. They live outside the city.`, `Anna: Oh, that's nice. Have fun!`, `Mark: Thanks! See you on Monday.`],
  tr: [`Anna: Oi, Mark! E aí, tudo bem?`, `Mark: Tudo bem, obrigado. E você?`, `Anna: Nada mal. Um pouco cansada. Foi uma semana longa.`,
       `Mark: Sei bem como é. Algum plano para o fim de semana?`, `Anna: Nada de especial. Talvez eu só fique em casa e descanse. E você?`,
       `Mark: Vou ver meus pais. Eles moram fora da cidade.`, `Anna: Ah, que legal. Divirta-se!`, `Mark: Valeu! Até segunda.`],
  chunks: [[`How's it going?`, `e aí, tudo bem?`], [`Pretty good, thanks`, `tudo bem, obrigado`], [`How about you?`, `e você?`], [`Not bad`, `nada mal`], [`I know what you mean`, `sei bem como é`], [`Any plans for the weekend?`, `algum plano pro fim de semana?`], [`Nothing special`, `nada de especial`], [`See you on Monday`, `até segunda`]],
  focus: `Small talk é a conversa rápida que nativos fazem o tempo todo. Decore as perguntas e respostas prontas: elas aparecem todo dia.`,
  tasks: [`Faça os dois papéis: leia a Anna, depois o Mark.`, `Responda de verdade: “Any plans for the weekend?”.`] },

{ d: 6, title: `My weekend`, pt: `Meu fim de semana`, lvl: 'A1',
  en: [`On weekends, I like to sleep late. On Saturday morning, I clean the house and go to the supermarket.`,
       `In the afternoon, I usually hang out with my friends. We go to a park or a bar near my place. We talk, laugh and sometimes play soccer.`,
       `On Sunday, I have lunch with my family. My mom cooks a lot of food, and everybody eats too much.`,
       `On Sunday night, I get ready for the week. I don't love Mondays, but I'm used to them.`],
  tr: [`Nos fins de semana, gosto de dormir até tarde. No sábado de manhã, limpo a casa e vou ao supermercado.`,
       `À tarde, normalmente saio com meus amigos. Vamos a um parque ou a um bar perto de casa. Conversamos, rimos e às vezes jogamos futebol.`,
       `No domingo, almoço com minha família. Minha mãe cozinha muita comida, e todo mundo come demais.`,
       `No domingo à noite, me preparo para a semana. Não amo segundas-feiras, mas já estou acostumado.`],
  chunks: [[`sleep late`, `dormir até tarde`], [`hang out with my friends`, `sair / ficar com meus amigos`], [`near my place`, `perto de casa`], [`everybody eats too much`, `todo mundo come demais`], [`get ready for`, `se preparar para`], [`I'm used to them`, `estou acostumado com elas`]],
  focus: `“On” com dias: on Saturday, on weekends. “In” com partes do dia: in the morning, in the afternoon. Exceção: at night.`,
  tasks: [`Conte o seu fim de semana típico em 4 frases.`, `Com quem você “hangs out”? Onde vocês vão?`] },

{ d: 7, title: `A normal week`, pt: `Uma semana normal`, lvl: 'A1', review: true,
  en: [`Let me tell you about my normal week. From Monday to Friday, I wake up early, take a quick shower and leave home at seven fifteen.`,
       `At work, I'm usually busy. I answer emails, go to meetings and try to finish everything on time. When I don't know something, I say, “Let me check and get back to you.”`,
       `I get home tired, make something simple for dinner and watch a series in English.`,
       `On weekends, I sleep late, hang out with my friends and have lunch with my family. It's a simple life, but I like it.`],
  tr: [`Deixa eu te contar sobre a minha semana normal. De segunda a sexta, acordo cedo, tomo um banho rápido e saio de casa às sete e quinze.`,
       `No trabalho, normalmente estou ocupado. Respondo e-mails, vou a reuniões e tento terminar tudo no prazo. Quando não sei algo, digo: “Deixa eu verificar e te retorno.”`,
       `Chego em casa cansado, faço algo simples para o jantar e assisto uma série em inglês.`,
       `Nos fins de semana, durmo até tarde, saio com meus amigos e almoço com minha família. É uma vida simples, mas eu gosto.`],
  chunks: [[`Let me tell you about`, `deixa eu te contar sobre`], [`From Monday to Friday`, `de segunda a sexta`], [`leave home`, `sair de casa`], [`on time`, `no prazo`], [`I get home tired`, `chego em casa cansado`], [`It's a simple life, but I like it`, `é uma vida simples, mas eu gosto`]],
  focus: `Revisão: este texto junta as expressões dos dias 1 a 6. Se alguma não veio na hora, volte ao dia dela.`,
  tasks: [`Grave 2 minutos contando a SUA semana normal. Guarde o áudio: no fim do mês você vai comparar.`, `Releia os textos 1 a 6 ouvindo, sem tradução.`] },

{ d: 8, title: `At the coffee shop`, pt: `Na cafeteria`, lvl: 'A1',
  en: [`Barista: Hi! What can I get for you?`, `Me: Hi! Can I get a large coffee, please?`, `Barista: Sure. Hot or iced?`,
       `Me: Hot, please. And I'd like a cheese sandwich too.`, `Barista: For here or to go?`, `Me: To go, please. How much is it?`,
       `Barista: That's eight fifty.`, `Me: Can I pay by card?`, `Barista: Of course. Here's your receipt. Have a nice day!`, `Me: Thanks, you too!`],
  tr: [`Barista: Oi! O que vai querer?`, `Eu: Oi! Pode me ver um café grande, por favor?`, `Barista: Claro. Quente ou gelado?`,
       `Eu: Quente, por favor. E eu queria um sanduíche de queijo também.`, `Barista: Para comer aqui ou para viagem?`, `Eu: Para viagem, por favor. Quanto fica?`,
       `Barista: Fica oito e cinquenta.`, `Eu: Posso pagar no cartão?`, `Barista: Claro. Aqui está seu recibo. Tenha um bom dia!`, `Eu: Obrigado, pra você também!`],
  chunks: [[`What can I get for you?`, `o que vai querer?`], [`Can I get`, `pode me ver… / eu queria…`], [`I'd like`, `eu gostaria de`], [`For here or to go?`, `pra comer aqui ou pra viagem?`], [`How much is it?`, `quanto custa?`], [`Can I pay by card?`, `posso pagar no cartão?`], [`you too`, `pra você também`]],
  focus: `Para pedir algo, nativos falam “Can I get…?” ou “I'd like…”. “I want…” soa seco demais.`,
  tasks: [`Peça o seu café da manhã ideal numa cafeteria imaginária.`, `Faça o papel do barista e do cliente.`] },

{ d: 9, title: `At the supermarket`, pt: `No supermercado`, lvl: 'A1',
  en: [`I need to buy some things for the week, so I go to the supermarket after work.`,
       `I can't find the eggs, so I ask an employee, “Excuse me, where can I find the eggs?” He says, “They're in aisle five, next to the milk.”`,
       `I also get some fruit, rice, chicken and coffee. I always forget something, so today I have a shopping list on my phone.`,
       `At the checkout, the cashier asks, “Do you need a bag?” I say, “No, thanks. I have one.”`,
       `Everything costs more than last month. Food is getting expensive!`],
  tr: [`Preciso comprar algumas coisas para a semana, então vou ao supermercado depois do trabalho.`,
       `Não acho os ovos, então pergunto a um funcionário: “Com licença, onde encontro os ovos?” Ele diz: “Estão no corredor cinco, ao lado do leite.”`,
       `Também pego frutas, arroz, frango e café. Sempre esqueço alguma coisa, então hoje tenho uma lista de compras no celular.`,
       `No caixa, a atendente pergunta: “Precisa de sacola?” Eu digo: “Não, obrigado. Tenho uma.”`,
       `Tudo custa mais que no mês passado. A comida está ficando cara!`],
  chunks: [[`I need to buy`, `preciso comprar`], [`Excuse me, where can I find`, `com licença, onde encontro…?`], [`next to`, `ao lado de`], [`shopping list`, `lista de compras`], [`Do you need a bag?`, `precisa de sacola?`], [`is getting expensive`, `está ficando caro`]],
  focus: `“Get” é o verbo coringa do inglês: get some fruit (pegar), getting expensive (ficando), get home (chegar).`,
  tasks: [`Faça a sua lista de compras da semana em inglês, em voz alta.`, `Pergunte onde ficam 3 produtos: “Excuse me, where can I find…?”.`] },

{ d: 10, title: `I'm lost`, pt: `Estou perdido`, lvl: 'A2',
  en: [`I'm in a new part of the city and I'm lost. My phone has no battery, so I need to ask for help.`,
       `I see a woman and say, “Excuse me, could you help me? I'm looking for the train station.”`,
       `She smiles and says, “Sure. Go straight for two blocks, then turn left. It's on your right, across from the bank.”`,
       `I don't understand everything, so I ask, “Sorry, could you say that again, a little slower?”`,
       `She repeats it slowly. I say, “Thank you so much!” and she says, “No problem. Good luck!”`],
  tr: [`Estou numa parte nova da cidade e estou perdido. Meu celular está sem bateria, então preciso pedir ajuda.`,
       `Vejo uma mulher e digo: “Com licença, você poderia me ajudar? Estou procurando a estação de trem.”`,
       `Ela sorri e diz: “Claro. Siga reto por duas quadras e depois vire à esquerda. Fica à sua direita, em frente ao banco.”`,
       `Não entendo tudo, então pergunto: “Desculpa, você poderia repetir, um pouco mais devagar?”`,
       `Ela repete devagar. Eu digo: “Muito obrigado!” e ela diz: “Imagina. Boa sorte!”`],
  chunks: [[`I'm lost`, `estou perdido`], [`could you help me?`, `você poderia me ajudar?`], [`I'm looking for`, `estou procurando`], [`Go straight`, `siga reto`], [`turn left`, `vire à esquerda`], [`on your right`, `à sua direita`], [`across from`, `em frente a`], [`could you say that again`, `poderia repetir?`]],
  focus: `“Could you say that again, a little slower?” é a frase que mais vai te salvar no começo. Não tenha vergonha de usar.`,
  tasks: [`Explique em inglês como ir da sua casa até a padaria mais próxima.`, `Treine pedir para repetir de 3 jeitos: “Sorry?”, “Could you say that again?”, “Could you speak a little slower?”.`] },

{ d: 11, title: `On the phone`, pt: `Ao telefone`, lvl: 'A2',
  en: [`My phone rings. It's my friend Paul.`, `Paul: Hey! Can you talk now?`, `Me: Sorry, I'm in a meeting. Can I call you back in ten minutes?`,
       `Paul: Sure, no problem.`, `Later, I call him back.`, `Me: Hi, Paul! Sorry about that. What's up?`,
       `Paul: Nothing much. I just wanted to ask if you're free tomorrow.`, `Me: Hold on, let me check… Yes, I'm free after six.`,
       `Paul: Great. I'll text you the address.`, `Me: Perfect. Talk to you later!`],
  tr: [`Meu celular toca. É meu amigo Paul.`, `Paul: Oi! Pode falar agora?`, `Eu: Desculpa, estou numa reunião. Posso te ligar de volta em dez minutos?`,
       `Paul: Claro, sem problema.`, `Mais tarde, ligo de volta pra ele.`, `Eu: Oi, Paul! Desculpa por aquilo. E aí, o que manda?`,
       `Paul: Nada de mais. Só queria perguntar se você está livre amanhã.`, `Eu: Espera, deixa eu ver… Sim, estou livre depois das seis.`,
       `Paul: Ótimo. Te mando o endereço por mensagem.`, `Eu: Perfeito. Falamos depois!`],
  chunks: [[`Can you talk now?`, `pode falar agora?`], [`Can I call you back`, `posso te ligar de volta?`], [`Sorry about that`, `desculpa por aquilo`], [`What's up?`, `e aí, o que manda?`], [`Nothing much`, `nada de mais`], [`Hold on, let me check`, `espera, deixa eu ver`], [`I'll text you`, `te mando mensagem`], [`Talk to you later`, `falamos depois`]],
  focus: `“Text” também é verbo: “I'll text you” = te mando mensagem. “Call back” = ligar de volta.`,
  tasks: [`Simule uma ligação marcando algo com um amigo.`, `Responda “What's up?” de 3 jeitos diferentes.`] },

{ d: 12, title: `Making plans`, pt: `Fazendo planos`, lvl: 'A2',
  en: [`Julia: Are you free on Saturday?`, `Me: I think so. Why?`, `Julia: There's a new Japanese restaurant downtown. Do you want to try it?`,
       `Me: Sounds good! What time?`, `Julia: How about seven?`, `Me: Seven is a bit early for me. Can we make it eight?`,
       `Julia: Sure, eight works for me. Let's meet in front of the restaurant.`, `Me: Okay. If something comes up, I'll let you know.`,
       `Julia: Perfect. See you on Saturday!`],
  tr: [`Julia: Você está livre no sábado?`, `Eu: Acho que sim. Por quê?`, `Julia: Tem um restaurante japonês novo no centro. Quer experimentar?`,
       `Eu: Boa! Que horas?`, `Julia: Que tal às sete?`, `Eu: Sete é um pouco cedo pra mim. Pode ser às oito?`,
       `Julia: Claro, oito funciona pra mim. Vamos nos encontrar na frente do restaurante.`, `Eu: Combinado. Se aparecer alguma coisa, eu te aviso.`,
       `Julia: Perfeito. Até sábado!`],
  chunks: [[`Are you free on`, `você está livre no/na…?`], [`I think so`, `acho que sim`], [`Do you want to`, `você quer…?`], [`Sounds good`, `boa! / parece bom`], [`How about`, `que tal…?`], [`Can we make it`, `pode ser às/no…?`], [`works for me`, `funciona pra mim`], [`If something comes up, I'll let you know`, `se aparecer algo, eu te aviso`]],
  focus: `“Let's…” convida: Let's meet, let's go, let's eat. É mais natural que “We can…”.`,
  tasks: [`Convide alguém para 3 programas diferentes usando “Do you want to…?” e “How about…?”.`, `Recuse um horário e proponha outro: “Can we make it…?”.`] },

{ d: 13, title: `I don't feel well`, pt: `Não estou me sentindo bem`, lvl: 'A2',
  en: [`Today I don't feel well. I have a headache and a sore throat, and I feel very tired.`,
       `I call my boss and say, “I'm sorry, I'm sick today. I can't come to work.”`,
       `In the afternoon, I go to the doctor. She asks, “What's wrong?” I tell her, “My throat hurts, and I have a fever.”`,
       `She says it's just a cold. “Drink a lot of water, take this medicine and get some rest.”`,
       `I go home, make some tea and stay in bed. I hope I feel better tomorrow.`],
  tr: [`Hoje não estou me sentindo bem. Estou com dor de cabeça e dor de garganta, e me sinto muito cansado.`,
       `Ligo para a minha chefe e digo: “Desculpa, estou doente hoje. Não posso ir trabalhar.”`,
       `À tarde, vou ao médico. Ela pergunta: “O que você tem?” Eu digo: “Minha garganta dói e estou com febre.”`,
       `Ela diz que é só um resfriado. “Beba bastante água, tome este remédio e descanse.”`,
       `Vou para casa, faço um chá e fico na cama. Espero me sentir melhor amanhã.`],
  chunks: [[`I don't feel well`, `não estou me sentindo bem`], [`I have a headache`, `estou com dor de cabeça`], [`I'm sick`, `estou doente`], [`What's wrong?`, `o que você tem?`], [`My throat hurts`, `minha garganta dói`], [`just a cold`, `só um resfriado`], [`get some rest`, `descansar`], [`I hope I feel better`, `espero me sentir melhor`]],
  focus: `Dor em inglês usa “have”: I have a headache, a stomachache, a fever. Ou “my … hurts”: my back hurts.`,
  tasks: [`Ligue (de mentira) para o trabalho avisando que está doente.`, `Descreva 3 sintomas diferentes com “I have…” e “My … hurts”.`] },

{ d: 14, title: `A busy Saturday`, pt: `Um sábado corrido`, lvl: 'A2', review: true,
  en: [`On Saturday, I have a lot to do. In the morning, I go to the coffee shop and say, “Can I get a large coffee to go, please?”`,
       `Then I go to the supermarket with my shopping list. I can't find the rice, so I ask, “Excuse me, where can I find the rice?”`,
       `In the afternoon, my friend calls, but I'm driving, so I say, “Can I call you back?” Later we make plans. “How about dinner at eight?” “Sounds good!”`,
       `At night, I feel a little tired, but I'm happy. It's a busy day, but a good one.`],
  tr: [`No sábado, tenho muita coisa para fazer. De manhã, vou à cafeteria e digo: “Pode me ver um café grande para viagem, por favor?”`,
       `Depois vou ao supermercado com minha lista de compras. Não acho o arroz, então pergunto: “Com licença, onde encontro o arroz?”`,
       `À tarde, meu amigo liga, mas estou dirigindo, então digo: “Posso te ligar de volta?” Mais tarde fazemos planos. “Que tal jantar às oito?” “Boa!”`,
       `À noite, me sinto um pouco cansado, mas estou feliz. É um dia corrido, mas um dia bom.`],
  chunks: [[`I have a lot to do`, `tenho muita coisa pra fazer`], [`Can I get`, `pode me ver…?`], [`shopping list`, `lista de compras`], [`Can I call you back?`, `posso te ligar de volta?`], [`How about`, `que tal…?`], [`a busy day, but a good one`, `um dia corrido, mas bom`]],
  focus: `Revisão: dias 8 a 13. Tente contar este texto com as suas palavras sem olhar.`,
  tasks: [`Grave 2 minutos contando o seu último sábado (pode ser no presente).`, `Ouça o áudio que você gravou no dia 7 e compare.`] },

{ d: 15, title: `Yesterday`, pt: `Ontem`, lvl: 'A2',
  en: [`Yesterday was a long day. I woke up at six, took a shower and left home early.`,
       `I had three meetings in the morning, so I didn't have time for coffee. At lunch, I ate a sandwich at my desk.`,
       `In the afternoon, I finished my report and sent it to my boss. She said, “Great job!” and I felt really good.`,
       `I got home at seven, made dinner and called my mom. We talked for an hour. I went to bed at eleven and slept very well.`],
  tr: [`Ontem foi um dia longo. Acordei às seis, tomei banho e saí de casa cedo.`,
       `Tive três reuniões de manhã, então não tive tempo para tomar café. No almoço, comi um sanduíche na minha mesa.`,
       `À tarde, terminei meu relatório e mandei para a minha chefe. Ela disse: “Ótimo trabalho!” e eu me senti muito bem.`,
       `Cheguei em casa às sete, fiz o jantar e liguei para minha mãe. Conversamos por uma hora. Fui dormir às onze e dormi muito bem.`],
  chunks: [[`Yesterday was`, `ontem foi`], [`I woke up`, `eu acordei`], [`left home early`, `saí de casa cedo`], [`I didn't have time`, `não tive tempo`], [`sent it to`, `mandei para`], [`I felt really good`, `me senti muito bem`], [`I got home`, `cheguei em casa`], [`We talked for an hour`, `conversamos por uma hora`]],
  focus: `Passado: regulares ganham -ed (finished, talked, called). Os mais usados são irregulares: woke, took, left, had, ate, sent, felt, got, went, slept. Negativa: didn't + verbo normal (I didn't have).`,
  tasks: [`Conte o seu dia de ontem, do acordar ao dormir.`, `Fale 3 coisas que você NÃO fez ontem: “I didn't…”.`] },

{ d: 16, title: `How was your weekend?`, pt: `Como foi seu fim de semana?`, lvl: 'A2',
  en: [`Ben: So, how was your weekend?`, `Me: It was great, thanks. How was yours?`, `Ben: Pretty quiet. I stayed home and watched movies. What did you do?`,
       `Me: On Saturday, I went to the beach with some friends.`, `Ben: Nice! Was it crowded?`,
       `Me: Yes, very crowded, but the water was perfect. We swam, ate fish and stayed there until sunset.`,
       `Ben: Sounds amazing. Did you do anything on Sunday?`, `Me: Not really. I was too tired. I just rested.`],
  tr: [`Ben: E aí, como foi seu fim de semana?`, `Eu: Foi ótimo, obrigado. E o seu?`, `Ben: Bem tranquilo. Fiquei em casa e assisti filmes. O que você fez?`,
       `Eu: No sábado, fui à praia com uns amigos.`, `Ben: Que legal! Estava cheia?`,
       `Eu: Sim, muito cheia, mas a água estava perfeita. Nadamos, comemos peixe e ficamos lá até o pôr do sol.`,
       `Ben: Parece incrível. Fez alguma coisa no domingo?`, `Eu: Não muito. Estava cansado demais. Só descansei.`],
  chunks: [[`how was your weekend?`, `como foi seu fim de semana?`], [`How was yours?`, `e o seu?`], [`Pretty quiet`, `bem tranquilo`], [`What did you do?`, `o que você fez?`], [`Was it crowded?`, `estava cheio?`], [`Sounds amazing`, `parece incrível`], [`Not really`, `não muito / na verdade não`], [`I was too tired`, `eu estava cansado demais`]],
  focus: `Pergunta no passado usa “did” e o verbo volta ao normal: What did you do? Did you go? Com o verbo to be, não tem did: Was it crowded? How was it?`,
  tasks: [`Responda de verdade: “How was your weekend?”.`, `Faça 3 perguntas no passado para um amigo imaginário.`] },

{ d: 17, title: `A bad day`, pt: `Um dia ruim`, lvl: 'A2',
  en: [`Last Tuesday was a terrible day. First, my alarm didn't go off, so I woke up late.`,
       `I ran to the bus stop, but I missed the bus. Then it started to rain, and I didn't have an umbrella.`,
       `When I finally got to work, I realized I forgot my laptop charger at home. My battery died before lunch.`,
       `In the evening, I wanted to relax, but the internet stopped working.`,
       `I laughed and thought, “Okay, today is not my day.” I went to bed early and hoped for a better tomorrow.`],
  tr: [`Terça passada foi um dia horrível. Primeiro, meu despertador não tocou, então acordei atrasado.`,
       `Corri até o ponto de ônibus, mas perdi o ônibus. Depois começou a chover, e eu não tinha guarda-chuva.`,
       `Quando finalmente cheguei no trabalho, percebi que esqueci o carregador do notebook em casa. Minha bateria acabou antes do almoço.`,
       `À noite, eu queria relaxar, mas a internet parou de funcionar.`,
       `Eu ri e pensei: “Ok, hoje não é o meu dia.” Fui dormir cedo e torci por um amanhã melhor.`],
  chunks: [[`my alarm didn't go off`, `meu despertador não tocou`], [`I woke up late`, `acordei atrasado`], [`I missed the bus`, `perdi o ônibus`], [`it started to rain`, `começou a chover`], [`I realized`, `eu percebi`], [`My battery died`, `minha bateria acabou`], [`stopped working`, `parou de funcionar`], [`today is not my day`, `hoje não é o meu dia`]],
  focus: `Cuidado com o falso cognato: “realize” = perceber, não “realizar”. Para realizar um sonho: “make a dream come true”.`,
  tasks: [`Conte um dia ruim que você teve, com pelo menos 4 problemas.`, `Use “First… Then… When I finally…” para dar ordem à história.`] },

{ d: 18, title: `A trip`, pt: `Uma viagem`, lvl: 'A2',
  en: [`Two years ago, I traveled to Rio de Janeiro with my cousin. It was my first time there.`,
       `We stayed in a small hotel near the beach. Every morning, we had breakfast and went out to explore the city.`,
       `We visited Christ the Redeemer and took the cable car to Sugarloaf Mountain. The view was amazing.`,
       `One night, we met some tourists from Canada. We spoke English with them all night. I was nervous at first, but they were very friendly.`,
       `It was one of the best trips of my life.`],
  tr: [`Dois anos atrás, viajei para o Rio de Janeiro com meu primo. Foi a minha primeira vez lá.`,
       `Ficamos num hotel pequeno perto da praia. Toda manhã, tomávamos café e saíamos para explorar a cidade.`,
       `Visitamos o Cristo Redentor e pegamos o bondinho até o Pão de Açúcar. A vista era incrível.`,
       `Uma noite, conhecemos uns turistas do Canadá. Falamos inglês com eles a noite toda. No começo fiquei nervoso, mas eles foram muito simpáticos.`,
       `Foi uma das melhores viagens da minha vida.`],
  chunks: [[`Two years ago`, `dois anos atrás`], [`It was my first time`, `foi a minha primeira vez`], [`We stayed in`, `ficamos em (hospedagem)`], [`went out to explore`, `saímos para explorar`], [`The view was amazing`, `a vista era incrível`], [`I was nervous at first`, `no começo fiquei nervoso`], [`one of the best trips of my life`, `uma das melhores viagens da minha vida`]],
  focus: `“Ago” vem depois do tempo: two years ago, a week ago, five minutes ago. E “met” (meet) no passado = conheci alguém.`,
  tasks: [`Conte uma viagem que você fez (ou um passeio), com onde ficou e o que fez.`, `Diga qual foi “one of the best… of my life” para você.`] },

{ d: 19, title: `My best friend`, pt: `Meu melhor amigo`, lvl: 'A2',
  en: [`I met my best friend, Rafael, in high school. On the first day, I didn't know anyone, and I was really shy.`,
       `During the break, he sat next to me and asked, “Do you play video games?” I said yes, and we talked for the whole break.`,
       `After that, we started hanging out every day. We studied together, played soccer and got in trouble a few times.`,
       `Now we live in different cities, but we still talk almost every week. When we see each other, it feels like nothing changed.`],
  tr: [`Conheci meu melhor amigo, Rafael, no ensino médio. No primeiro dia, eu não conhecia ninguém e estava muito tímido.`,
       `No intervalo, ele sentou do meu lado e perguntou: “Você joga videogame?” Eu disse que sim, e conversamos o intervalo inteiro.`,
       `Depois disso, começamos a andar juntos todo dia. Estudávamos juntos, jogávamos futebol e nos metemos em encrenca algumas vezes.`,
       `Hoje moramos em cidades diferentes, mas ainda conversamos quase toda semana. Quando nos vemos, parece que nada mudou.`],
  chunks: [[`I met my best friend`, `conheci meu melhor amigo`], [`I didn't know anyone`, `não conhecia ninguém`], [`I was really shy`, `eu era muito tímido`], [`sat next to me`, `sentou do meu lado`], [`we started hanging out`, `começamos a andar juntos`], [`got in trouble`, `nos metemos em encrenca`], [`we still talk`, `ainda conversamos`], [`it feels like nothing changed`, `parece que nada mudou`]],
  focus: `“Still” = ainda (algo que continua). “Each other” = um ao outro: we see each other, we help each other.`,
  tasks: [`Conte como você conheceu o seu melhor amigo ou amiga.`, `O que vocês ainda fazem juntos? Use “we still…”.`] },

{ d: 20, title: `My funny mistakes`, pt: `Meus erros engraçados`, lvl: 'A2',
  en: [`At a party last year, an American guy asked me, “How old are you?” I was nervous, and I said, “I have twenty-eight years.”`,
       `He smiled and said, “Oh, you mean you're twenty-eight!” I felt embarrassed, but he was really nice about it.`,
       `Later, I made another mistake. I said, “I pretend to study more.” But “pretend” means fingir! The right way is “I intend to study more,” or simply “I plan to study more.”`,
       `That day I learned something important: mistakes are part of learning. If you're afraid of mistakes, you don't speak. And if you don't speak, you don't improve.`],
  tr: [`Numa festa no ano passado, um americano me perguntou: “Quantos anos você tem?” Eu estava nervoso e disse: “I have twenty-eight years.”`,
       `Ele sorriu e disse: “Ah, você quer dizer que tem vinte e oito!” Fiquei com vergonha, mas ele foi muito legal.`,
       `Depois, cometi outro erro. Eu disse “I pretend to study more”. Mas “pretend” significa fingir! O certo é “I intend to study more”, ou simplesmente “I plan to study more” (pretendo estudar mais).`,
       `Naquele dia aprendi algo importante: errar faz parte de aprender. Se você tem medo de errar, não fala. E se não fala, não melhora.`],
  chunks: [[`How old are you?`, `quantos anos você tem?`], [`you mean`, `você quer dizer`], [`I felt embarrassed`, `fiquei com vergonha`], [`he was really nice about it`, `ele foi muito legal com isso`], [`I plan to`, `eu pretendo`], [`mistakes are part of learning`, `errar faz parte de aprender`], [`you don't improve`, `você não melhora`]],
  focus: `Falsos cognatos que brasileiros mais erram: pretend (fingir), actually (na verdade), push (empurrar), college (faculdade), exquisite (requintado), lunch (almoço, não lanche).`,
  tasks: [`Conte um erro ou mico que você já pagou, em inglês ou não.`, `Faça uma frase certa com: actually, I plan to, I'm … years old.`] },

{ d: 21, title: `Last week`, pt: `Semana passada`, lvl: 'A2', review: true,
  en: [`Last week was busy, but good. On Monday, my alarm didn't go off and I missed the bus. Not a great start!`,
       `On Wednesday, I finished a big report, and my boss said, “Great job!” I felt really good.`,
       `On Friday, I met my best friend for dinner. We talked for hours, and it felt like nothing changed.`,
       `On the weekend, I went to the beach. It was crowded, but the water was perfect.`,
       `When my coworker asked, “How was your week?” I said, “It was crazy, but I enjoyed it.”`],
  tr: [`Semana passada foi corrida, mas boa. Na segunda, meu despertador não tocou e perdi o ônibus. Não foi um bom começo!`,
       `Na quarta, terminei um relatório grande, e minha chefe disse: “Ótimo trabalho!” Me senti muito bem.`,
       `Na sexta, encontrei meu melhor amigo para jantar. Conversamos por horas, e parecia que nada tinha mudado.`,
       `No fim de semana, fui à praia. Estava cheia, mas a água estava perfeita.`,
       `Quando meu colega perguntou “Como foi sua semana?”, eu disse: “Foi uma loucura, mas eu curti.”`],
  chunks: [[`Not a great start`, `não foi um bom começo`], [`I felt really good`, `me senti muito bem`], [`We talked for hours`, `conversamos por horas`], [`It was crowded`, `estava cheio`], [`How was your week?`, `como foi sua semana?`], [`It was crazy, but I enjoyed it`, `foi uma loucura, mas eu curti`]],
  focus: `Revisão do passado: dias 15 a 20. Se você trocar algum verbo irregular, anote e repita 5 vezes.`,
  tasks: [`Grave 2 minutos contando a sua semana passada, no passado.`, `Compare com o áudio do dia 14: você já usa o passado?`] },

{ d: 22, title: `Next week`, pt: `Semana que vem`, lvl: 'A2',
  en: [`Next week is going to be busy. On Monday, I'm going to start a new project at work, and I'm a little nervous about it.`,
       `On Wednesday, I'm going to visit my grandmother. She's turning eighty, so we're going to have a small party.`,
       `I want to study more English, too. I'm going to watch one video every day and write five sentences about my day.`,
       `I think it will be a good week. And if something goes wrong, I'll figure it out.`],
  tr: [`A semana que vem vai ser corrida. Na segunda, vou começar um projeto novo no trabalho, e estou um pouco nervoso com isso.`,
       `Na quarta, vou visitar minha avó. Ela vai fazer oitenta anos, então vamos fazer uma festinha.`,
       `Também quero estudar mais inglês. Vou assistir um vídeo por dia e escrever cinco frases sobre o meu dia.`,
       `Acho que vai ser uma boa semana. E se algo der errado, eu dou um jeito.`],
  chunks: [[`is going to be busy`, `vai ser corrida`], [`I'm going to start`, `vou começar`], [`a little nervous about it`, `um pouco nervoso com isso`], [`She's turning eighty`, `ela vai fazer oitenta anos`], [`I think it will be`, `acho que vai ser`], [`if something goes wrong`, `se algo der errado`], [`I'll figure it out`, `eu dou um jeito`]],
  focus: `“Going to” = plano já decidido (I'm going to visit). “Will” = decisão na hora ou opinião sobre o futuro (I think it will be good; I'll figure it out).`,
  tasks: [`Conte 4 planos para a sua próxima semana com “I'm going to…”.`, `Diga uma previsão com “I think it will…”.`] },

{ d: 23, title: `What do you think?`, pt: `O que você acha?`, lvl: 'A2',
  en: [`Ana: What do you think about working from home?`, `Me: I think it's great. I don't waste time in traffic, and I can focus better.`,
       `Ana: Really? In my opinion, it's a bit lonely. I miss talking to people.`, `Me: I see your point. That's true, sometimes I feel lonely too.`,
       `Ana: So, do you prefer working from home or at the office?`, `Me: Honestly, I'd say a mix of both is ideal. Two or three days at home is perfect for me.`,
       `Ana: Yeah, I agree with that.`],
  tr: [`Ana: O que você acha de trabalhar de casa?`, `Eu: Acho ótimo. Não perco tempo no trânsito e consigo me concentrar melhor.`,
       `Ana: Sério? Na minha opinião, é meio solitário. Sinto falta de conversar com as pessoas.`, `Eu: Entendo o seu ponto. É verdade, às vezes também me sinto sozinho.`,
       `Ana: Então, você prefere trabalhar de casa ou no escritório?`, `Eu: Sinceramente, eu diria que um pouco dos dois é o ideal. Dois ou três dias em casa é perfeito pra mim.`,
       `Ana: É, concordo com isso.`],
  chunks: [[`What do you think about`, `o que você acha de…?`], [`I think`, `eu acho`], [`In my opinion`, `na minha opinião`], [`I miss talking to people`, `sinto falta de conversar com as pessoas`], [`I see your point`, `entendo o seu ponto`], [`That's true`, `é verdade`], [`Honestly, I'd say`, `sinceramente, eu diria`], [`I agree with that`, `concordo com isso`]],
  focus: `“I agree” sem “am”. Nunca “I am agree”. Para discordar com educação: “I'm not sure about that” ou “I see your point, but…”.`,
  tasks: [`Dê sua opinião sobre trabalhar de casa, com um motivo.`, `Escolha um tema (futebol, redes sociais, cidade grande) e diga uma opinião, concordando e discordando.`] },

{ d: 24, title: `My goal`, pt: `Minha meta`, lvl: 'A2',
  en: [`I've been studying English for a few months now. At the beginning, I couldn't understand anything in movies. Now I understand some sentences, and that makes me happy.`,
       `My goal is to have a real conversation without being afraid. I want to speak in meetings at work and travel without problems.`,
       `I know it takes time. Some days I'm tired and I don't want to study. On those days, I do just ten minutes. Ten minutes is better than nothing.`,
       `Little by little, I'm getting better.`],
  tr: [`Estou estudando inglês há alguns meses. No começo, eu não entendia nada nos filmes. Agora entendo algumas frases, e isso me deixa feliz.`,
       `Minha meta é ter uma conversa de verdade sem medo. Quero falar em reuniões no trabalho e viajar sem problemas.`,
       `Sei que leva tempo. Alguns dias estou cansado e não quero estudar. Nesses dias, faço só dez minutos. Dez minutos é melhor que nada.`,
       `Pouco a pouco, estou melhorando.`],
  chunks: [[`I've been studying English for`, `estudo inglês há…`], [`At the beginning`, `no começo`], [`I couldn't understand anything`, `eu não entendia nada`], [`My goal is to`, `minha meta é`], [`without being afraid`, `sem ter medo`], [`it takes time`, `leva tempo`], [`better than nothing`, `melhor que nada`], [`Little by little`, `pouco a pouco`], [`I'm getting better`, `estou melhorando`]],
  focus: `“Há quanto tempo” em inglês usa o present perfect: I've been studying for 3 months (estudo há 3 meses). Nunca “I study since 3 months”.`,
  tasks: [`Diga há quanto tempo você estuda inglês e qual é a sua meta.`, `Fale 2 coisas que você não conseguia fazer e agora consegue: “I couldn't… Now I can…”.`] },

{ d: 25, title: `Job interview`, pt: `Entrevista de emprego`, lvl: 'A2',
  en: [`Interviewer: So, tell me a little about yourself.`, `Me: Sure. I work with business systems, mainly SAP, and I have three years of experience in the area.`,
       `Interviewer: Why are you interested in this position?`, `Me: Because I want to grow in my career, and I really like what your company does.`,
       `Interviewer: What are your strengths?`, `Me: I'm organized, I learn fast, and I work well in a team.`,
       `Interviewer: And what about your weaknesses?`, `Me: Sometimes I spend too much time on details. I'm working on that.`,
       `Interviewer: Great. Do you have any questions for us?`, `Me: Yes. What does a typical day look like in this role?`],
  tr: [`Entrevistadora: Então, me fale um pouco sobre você.`, `Eu: Claro. Trabalho com sistemas empresariais, principalmente SAP, e tenho três anos de experiência na área.`,
       `Entrevistadora: Por que você tem interesse nesta vaga?`, `Eu: Porque quero crescer na minha carreira, e gosto muito do que a sua empresa faz.`,
       `Entrevistadora: Quais são seus pontos fortes?`, `Eu: Sou organizado, aprendo rápido e trabalho bem em equipe.`,
       `Entrevistadora: E seus pontos fracos?`, `Eu: Às vezes passo tempo demais nos detalhes. Estou trabalhando nisso.`,
       `Entrevistadora: Ótimo. Você tem alguma pergunta para nós?`, `Eu: Sim. Como é um dia típico nesta função?`],
  chunks: [[`tell me a little about yourself`, `me fale um pouco sobre você`], [`I have three years of experience`, `tenho três anos de experiência`], [`Why are you interested in`, `por que você tem interesse em…?`], [`I want to grow in my career`, `quero crescer na carreira`], [`I work well in a team`, `trabalho bem em equipe`], [`I'm working on that`, `estou trabalhando nisso`], [`Do you have any questions for us?`, `tem alguma pergunta pra nós?`], [`What does a typical day look like`, `como é um dia típico…?`]],
  focus: `Prepare a resposta do “Tell me about yourself” e decore. Ela aparece em toda entrevista, e é a primeira impressão.`,
  tasks: [`Responda as 5 perguntas com a sua experiência real.`, `Grave a resposta do “Tell me about yourself” em até 1 minuto.`] },

{ d: 26, title: `A work email`, pt: `Um e-mail de trabalho`, lvl: 'A2',
  en: [`Subject: Sales report for Friday`, `Hi Sarah,`, `I hope you're doing well.`,
       `I'm writing to ask about the sales report. Could you please send me the numbers from last month by Thursday? I need them to finish the presentation for Friday.`,
       `If you have any questions, just let me know. I'm happy to help.`, `Thanks in advance!`, `Best regards,`, `Lucas`],
  tr: [`Assunto: Relatório de vendas para sexta`, `Oi Sarah,`, `Espero que esteja tudo bem.`,
       `Estou escrevendo para perguntar sobre o relatório de vendas. Você poderia, por favor, me mandar os números do mês passado até quinta? Preciso deles para terminar a apresentação de sexta.`,
       `Se tiver alguma dúvida, é só me avisar. Fico feliz em ajudar.`, `Desde já, obrigado!`, `Atenciosamente,`, `Lucas`],
  chunks: [[`I hope you're doing well`, `espero que esteja tudo bem`], [`I'm writing to ask about`, `escrevo para perguntar sobre`], [`Could you please send me`, `você poderia me mandar…?`], [`by Thursday`, `até quinta`], [`just let me know`, `é só me avisar`], [`I'm happy to help`, `fico feliz em ajudar`], [`Thanks in advance`, `desde já, obrigado`], [`Best regards`, `atenciosamente`]],
  focus: `“By” + dia = prazo (até): by Thursday, by the end of the day. “Until” é duração: I work until six.`,
  tasks: [`Escreva um e-mail curto pedindo algo a um colega, usando 4 expressões marcadas.`, `Passe o seu e-mail no LanguageTool e veja o que ele corrige.`] },

{ d: 27, title: `An online meeting`, pt: `Uma reunião online`, lvl: 'A2',
  en: [`Tom: Hi everyone, can you hear me okay?`, `Kate: Yes, we can hear you.`, `Tom: Great. Let's get started. Lucas, can you share your screen?`,
       `Me: Sure, one second… Can you see it now?`, `Tom: Yes, perfect.`, `Me: Okay, so this is the plan for next month…`,
       `Kate: Sorry, Lucas, you're on mute.`, `Me: Oh, sorry! Can you hear me now?`, `Kate: Yes, much better.`,
       `Me: …and that's it. Any questions?`, `Kate: Just one. Can we talk about the deadline later?`, `Tom: Sure. Let's wrap up here. Thanks, everyone!`],
  tr: [`Tom: Oi, pessoal, estão me ouvindo bem?`, `Kate: Sim, estamos te ouvindo.`, `Tom: Ótimo. Vamos começar. Lucas, pode compartilhar sua tela?`,
       `Eu: Claro, um segundo… Estão vendo agora?`, `Tom: Sim, perfeito.`, `Eu: Ok, então este é o plano para o mês que vem…`,
       `Kate: Desculpa, Lucas, você está no mudo.`, `Eu: Ah, desculpa! Estão me ouvindo agora?`, `Kate: Sim, bem melhor.`,
       `Eu: …e é isso. Alguma pergunta?`, `Kate: Só uma. Podemos falar sobre o prazo depois?`, `Tom: Claro. Vamos encerrar por aqui. Obrigado, pessoal!`],
  chunks: [[`can you hear me okay?`, `estão me ouvindo bem?`], [`Let's get started`, `vamos começar`], [`share your screen`, `compartilhar sua tela`], [`Can you see it now?`, `estão vendo agora?`], [`you're on mute`, `você está no mudo`], [`much better`, `bem melhor`], [`Any questions?`, `alguma pergunta?`], [`Let's wrap up`, `vamos encerrar`]],
  focus: `Essas frases aparecem em toda reunião online. Se você trabalha com equipes de fora, elas valem ouro.`,
  tasks: [`Abra e conduza uma reunião imaginária de 1 minuto: comece, compartilhe a tela, encerre.`, `Apresente em 3 frases o que você fez no trabalho esta semana.`] },

{ d: 28, title: `My English journey`, pt: `Minha jornada no inglês`, lvl: 'A2', review: true,
  en: [`A month ago, I decided to take my English seriously. Now I have a routine: I read one text every day, listen to it and repeat it out loud.`,
       `I learned how to talk about my day, order coffee, ask for directions and make plans with friends. I can also tell stories about the past and talk about my goals.`,
       `I still make mistakes, and that's okay. Mistakes are part of learning.`,
       `Next month, I'm going to talk more, listen more and keep going. Little by little, I'm getting better.`],
  tr: [`Um mês atrás, decidi levar meu inglês a sério. Agora tenho uma rotina: leio um texto por dia, escuto e repito em voz alta.`,
       `Aprendi a falar do meu dia, pedir um café, pedir informação e fazer planos com amigos. Também consigo contar histórias no passado e falar das minhas metas.`,
       `Ainda cometo erros, e tudo bem. Errar faz parte de aprender.`,
       `No mês que vem, vou falar mais, ouvir mais e continuar. Pouco a pouco, estou melhorando.`],
  chunks: [[`A month ago`, `um mês atrás`], [`take my English seriously`, `levar meu inglês a sério`], [`repeat it out loud`, `repetir em voz alta`], [`I learned how to`, `aprendi a`], [`I still make mistakes`, `ainda cometo erros`], [`keep going`, `continuar`], [`I'm getting better`, `estou melhorando`]],
  focus: `Revisão do mês inteiro. “Make a mistake” (não “do”): cometer um erro.`,
  tasks: [`Grave 2 minutos contando o que você aprendeu este mês.`, `Ouça o seu áudio do dia 7 e o de hoje, um depois do outro. Repare na diferença.`] },

{ d: 29, title: `Words natives use all the time`, pt: `Palavras que nativos usam o tempo todo`, lvl: 'A2',
  en: [`When people speak English in real life, they use a lot of small words that don't appear in textbooks.`,
       `“Actually” is used to correct or add information: “Actually, I don't drink coffee.” “I mean” explains what you just said: “It's good… I mean, it's not perfect.”`,
       `“Kind of” means more or less: “I'm kind of tired.” “You know” gives you time to think: “It's, you know, a little complicated.”`,
       `“No worries” means no problem, and “I'm down” means I'm in, I want to go. And when you need a moment, just say, “Let me think.”`,
       `Use these words, and you'll sound much more natural.`],
  tr: [`Quando as pessoas falam inglês na vida real, usam muitas palavrinhas que não aparecem nos livros.`,
       `“Actually” serve para corrigir ou acrescentar algo: “Na verdade, eu não tomo café.” “I mean” explica o que você acabou de dizer: “É bom… quer dizer, não é perfeito.”`,
       `“Kind of” significa mais ou menos: “Tô meio cansado.” “You know” te dá tempo para pensar: “É, sabe, meio complicado.”`,
       `“No worries” significa sem problema, e “I'm down” significa tô dentro, quero ir. E quando você precisar de um momento, é só dizer: “Deixa eu pensar.”`,
       `Use essas palavras e você vai soar muito mais natural.`],
  chunks: [[`Actually`, `na verdade (não é “atualmente”!)`], [`I mean`, `quer dizer`], [`Kind of`, `meio / mais ou menos`], [`You know`, `sabe / tipo`], [`No worries`, `sem problema / de boa`], [`I'm down`, `tô dentro`], [`Let me think`, `deixa eu pensar`]],
  focus: `Esses “filler words” dão tempo para você pensar sem travar. Em vez de “éééé”, diga “Let me think…” ou “you know…”.`,
  tasks: [`Faça uma frase sua com cada uma das 7 expressões.`, `Responda a um convite com “I'm down!” e a um pedido de desculpas com “No worries”.`] },

{ d: 30, title: `One minute about me`, pt: `Um minuto sobre mim`, lvl: 'A2',
  en: [`Now it's your turn. Here's a model you can use to talk about yourself for one minute.`,
       `Hi, I'm Lucas. I'm from Brazil, and I work with business systems. On a normal day, I wake up early, go to work and study English at night.`,
       `Last year, I decided to learn English because I want to grow in my career and travel more. At first, it was hard, but now I can have simple conversations.`,
       `In the future, I'm going to work with international teams. I know it takes time, but I'm getting better every day.`],
  tr: [`Agora é a sua vez. Aqui está um modelo que você pode usar para falar de você por um minuto.`,
       `Oi, eu sou o Lucas. Sou do Brasil e trabalho com sistemas empresariais. Num dia normal, acordo cedo, vou trabalhar e estudo inglês à noite.`,
       `No ano passado, decidi aprender inglês porque quero crescer na carreira e viajar mais. No começo foi difícil, mas agora consigo ter conversas simples.`,
       `No futuro, vou trabalhar com equipes internacionais. Sei que leva tempo, mas estou melhorando a cada dia.`],
  chunks: [[`it's your turn`, `é a sua vez`], [`On a normal day`, `num dia normal`], [`I decided to learn English`, `decidi aprender inglês`], [`At first, it was hard`, `no começo foi difícil`], [`now I can have simple conversations`, `agora consigo ter conversas simples`], [`In the future`, `no futuro`], [`every day`, `todo dia`]],
  focus: `Este texto usa presente, passado e futuro juntos. Se você consegue falar ele com os seus dados, terminou bem o mês 1.`,
  tasks: [`Troque os dados pelos seus e grave 1 minuto sem ler. Esse é o seu teste do mês.`, `Mande o áudio para um amigo ou guarde para comparar no mês 3.`] },
{ d: 31, title: `My neighborhood`, pt: `Meu bairro`, lvl: 'A2',
  en: [`I live in a quiet neighborhood, about twenty minutes from downtown. There's a bakery on my street, and there are two supermarkets near my building.`,
       `There isn't a gym close to my place, so I walk fifteen minutes to get to one. There's also a small park where people walk their dogs in the evening.`,
       `The best thing about my neighborhood is the people. Everybody says hi, and the guy at the bakery knows my name.`,
       `The worst thing is the noise on Friday nights. But overall, I really like living here.`],
  tr: [`Moro num bairro tranquilo, a uns vinte minutos do centro. Tem uma padaria na minha rua, e tem dois supermercados perto do meu prédio.`,
       `Não tem academia perto de casa, então ando quinze minutos para chegar numa. Também tem uma pracinha onde as pessoas passeiam com os cachorros à noite.`,
       `A melhor coisa do meu bairro são as pessoas. Todo mundo cumprimenta, e o rapaz da padaria sabe o meu nome.`,
       `A pior coisa é o barulho nas sextas à noite. Mas, no geral, eu gosto muito de morar aqui.`],
  chunks: [[`I live in a quiet neighborhood`, `moro num bairro tranquilo`], [`about twenty minutes from`, `a uns vinte minutos de`], [`There's a bakery`, `tem uma padaria`], [`there are two supermarkets`, `tem dois supermercados`], [`There isn't`, `não tem`], [`close to my place`, `perto de casa`], [`The best thing about`, `a melhor coisa de`], [`overall`, `no geral`]],
  focus: `“Tem” de existir é “there is” (um) e “there are” (vários). “I have” é só posse. Nunca diga “have a bakery on my street”.`,
  tasks: [`Descreva o seu bairro com 3 frases com “there is / there are” e 1 com “there isn't”.`, `Qual é a melhor e a pior coisa de onde você mora?`] },

{ d: 32, title: `Looking for an apartment`, pt: `Procurando apartamento`, lvl: 'A2',
  en: [`Agent: Hi! So, what are you looking for?`, `Me: I'm looking for a one-bedroom apartment, close to the subway if possible.`,
       `Agent: Okay. What's your budget?`, `Me: Around fifteen hundred a month. I can't pay more than that.`,
       `Agent: I have one here. It's on the fourth floor, and it gets a lot of sunlight.`, `Me: Sounds nice. Is it furnished?`,
       `Agent: Partly. It comes with a fridge and a stove. Utilities aren't included.`, `Me: Got it. Can I take a look at it this week?`,
       `Agent: Sure. How about Thursday at five?`, `Me: That works. Thanks!`],
  tr: [`Corretora: Oi! Então, o que você está procurando?`, `Eu: Estou procurando um apartamento de um quarto, perto do metrô se possível.`,
       `Corretora: Certo. Qual é o seu orçamento?`, `Eu: Uns mil e quinhentos por mês. Não consigo pagar mais que isso.`,
       `Corretora: Tenho um aqui. Fica no quarto andar e bate bastante sol.`, `Eu: Parece legal. É mobiliado?`,
       `Corretora: Em parte. Vem com geladeira e fogão. As contas (água, luz) não estão incluídas.`, `Eu: Entendi. Posso dar uma olhada nele esta semana?`,
       `Corretora: Claro. Que tal quinta às cinco?`, `Eu: Fechado. Obrigado!`],
  chunks: [[`what are you looking for?`, `o que você está procurando?`], [`if possible`, `se possível`], [`What's your budget?`, `qual é o seu orçamento?`], [`I can't pay more than that`, `não consigo pagar mais que isso`], [`Is it furnished?`, `é mobiliado?`], [`It comes with`, `vem com`], [`Got it`, `entendi`], [`Can I take a look at it`, `posso dar uma olhada?`]],
  focus: `“Got it” é o jeito mais comum de dizer “entendi” na conversa. “I understood” soa formal demais no dia a dia.`,
  tasks: [`Descreva o apartamento dos seus sonhos para um corretor.`, `Faça 3 perguntas sobre um imóvel: “Is it…? Does it have…? How much…?”.`] },

{ d: 33, title: `Shopping for clothes`, pt: `Comprando roupa`, lvl: 'A2',
  en: [`Clerk: Hi there! Can I help you find anything?`, `Me: I'm just looking, thanks. Actually, do you have this shirt in blue?`,
       `Clerk: Let me see… Yes, we do. What size are you?`, `Me: Medium, I think.`, `Clerk: Here you go. The fitting rooms are over there.`,
       `Me: Thanks. Can I try this on too?`, `Later…`, `Me: The shirt fits perfectly, but the jeans are too tight. Do you have them in a bigger size?`,
       `Clerk: Sorry, we're out of that size. But this other style is on sale.`, `Me: Okay, I'll take the shirt for now.`],
  tr: [`Vendedora: Oi! Posso te ajudar a encontrar alguma coisa?`, `Eu: Só estou olhando, obrigado. Na verdade, vocês têm essa camisa em azul?`,
       `Vendedora: Deixa eu ver… Sim, temos. Qual é o seu tamanho?`, `Eu: M, acho.`, `Vendedora: Aqui está. Os provadores ficam ali.`,
       `Eu: Obrigado. Posso provar esta também?`, `Mais tarde…`, `Eu: A camisa serviu perfeitamente, mas a calça jeans está apertada demais. Vocês têm um tamanho maior?`,
       `Vendedora: Desculpa, esse tamanho acabou. Mas este outro modelo está em promoção.`, `Eu: Tudo bem, vou levar a camisa por enquanto.`],
  chunks: [[`Can I help you find anything?`, `posso te ajudar a achar algo?`], [`I'm just looking`, `só estou olhando`], [`What size are you?`, `qual o seu tamanho?`], [`Here you go`, `aqui está`], [`Can I try this on`, `posso provar isto?`], [`fits perfectly`, `serviu perfeitamente`], [`too tight`, `apertado demais`], [`we're out of`, `acabou / está em falta`], [`on sale`, `em promoção`], [`I'll take`, `vou levar`]],
  focus: `“Too” = demais (problema): too tight, too expensive. “Very” = muito (sem problema): very nice. “Try on” = provar roupa.`,
  tasks: [`Simule uma compra de roupa: peça cor, tamanho e prove.`, `Diga 3 problemas com “too”: too big, too small, too expensive…`] },

{ d: 34, title: `Returning something`, pt: `Devolvendo uma compra`, lvl: 'A2',
  en: [`Me: Hi. I bought these headphones here last week, and I'd like to return them.`, `Clerk: Sure. What's the problem with them?`,
       `Me: The left side doesn't work. I tried them on two different phones.`, `Clerk: I'm sorry about that. Do you have the receipt?`,
       `Me: Yes, here it is.`, `Clerk: Thanks. Would you like a refund or an exchange?`,
       `Me: An exchange, please. I still want the same model.`, `Clerk: No problem. Let me get a new pair for you. Just a moment.`,
       `Me: Thanks for your help.`, `Clerk: You're welcome. Sorry for the trouble.`],
  tr: [`Eu: Oi. Comprei estes fones aqui semana passada e gostaria de devolver.`, `Atendente: Claro. Qual é o problema com eles?`,
       `Eu: O lado esquerdo não funciona. Testei em dois celulares diferentes.`, `Atendente: Sinto muito por isso. Você tem a nota fiscal?`,
       `Eu: Sim, aqui está.`, `Atendente: Obrigado. Você prefere reembolso ou troca?`,
       `Eu: Troca, por favor. Ainda quero o mesmo modelo.`, `Atendente: Sem problema. Vou pegar um par novo para você. Só um momento.`,
       `Eu: Obrigado pela ajuda.`, `Atendente: De nada. Desculpe pelo transtorno.`],
  chunks: [[`I'd like to return them`, `gostaria de devolver`], [`What's the problem with`, `qual é o problema com…?`], [`doesn't work`, `não funciona`], [`Do you have the receipt?`, `tem a nota?`], [`here it is`, `aqui está`], [`a refund or an exchange`, `reembolso ou troca`], [`Just a moment`, `só um momento`], [`Thanks for your help`, `obrigado pela ajuda`], [`Sorry for the trouble`, `desculpe o transtorno`]],
  focus: `“Return” = devolver. Para voltar a um lugar também: I'll return tomorrow. Mas no dia a dia, para pessoas, nativos preferem “come back”.`,
  tasks: [`Devolva algo com defeito: diga o que comprou, quando, e qual é o problema.`, `Faça os dois papéis: cliente e atendente.`] },

{ d: 35, title: `At a restaurant`, pt: `No restaurante`, lvl: 'A2',
  en: [`Waiter: Good evening! A table for two?`, `Me: Yes, please. Could we sit by the window?`, `Waiter: Of course. Here are your menus. Can I get you something to drink?`,
       `Me: Just water for now, thanks.`, `Waiter: Are you ready to order?`, `Me: Almost. What do you recommend?`,
       `Waiter: The grilled chicken is very popular.`, `Me: Great, I'll have the chicken with fries. And could I have the sauce on the side?`,
       `Waiter: Sure thing. Anything else?`, `Me: No, that's all. And later, could we get the check, please?`],
  tr: [`Garçom: Boa noite! Mesa para dois?`, `Eu: Sim, por favor. Podemos sentar perto da janela?`, `Garçom: Claro. Aqui estão os cardápios. Posso trazer algo para beber?`,
       `Eu: Só água por enquanto, obrigado.`, `Garçom: Já podem pedir?`, `Eu: Quase. O que você recomenda?`,
       `Garçom: O frango grelhado faz muito sucesso.`, `Eu: Ótimo, vou querer o frango com batata frita. E pode trazer o molho à parte?`,
       `Garçom: Claro. Mais alguma coisa?`, `Eu: Não, é só isso. E depois, pode trazer a conta, por favor?`],
  chunks: [[`A table for two?`, `mesa para dois?`], [`Could we sit by the window?`, `podemos sentar perto da janela?`], [`for now`, `por enquanto`], [`Are you ready to order?`, `já podem pedir?`], [`What do you recommend?`, `o que você recomenda?`], [`I'll have`, `vou querer`], [`on the side`, `à parte`], [`Anything else?`, `mais alguma coisa?`], [`that's all`, `é só isso`], [`the check`, `a conta`]],
  focus: `No restaurante, “I'll have…” é a forma mais natural de pedir. A conta é “the check” nos EUA e “the bill” no Reino Unido.`,
  tasks: [`Peça entrada, prato principal e bebida num restaurante imaginário.`, `Peça uma mudança no prato: sem cebola, molho à parte…`] },

{ d: 36, title: `Cooking with a friend`, pt: `Cozinhando com um amigo`, lvl: 'A2',
  en: [`Leo: What are you doing?`, `Me: I'm cutting the onions. Can you wash the tomatoes?`, `Leo: Sure. Are you making pasta again?`,
       `Me: Yes, but today I'm trying a new recipe. I'm following a video on YouTube.`, `Leo: Is the water boiling yet?`,
       `Me: Not yet. Can you turn up the heat a little?`, `Leo: Done. Wow, it smells really good.`,
       `Me: Thanks! Can you taste the sauce? Does it need more salt?`, `Leo: Hmm, maybe a little. It's almost perfect.`,
       `Me: Great. Let's eat in five minutes.`],
  tr: [`Leo: O que você está fazendo?`, `Eu: Estou cortando as cebolas. Você pode lavar os tomates?`, `Leo: Claro. Vai fazer macarrão de novo?`,
       `Eu: Sim, mas hoje estou testando uma receita nova. Estou seguindo um vídeo no YouTube.`, `Leo: A água já está fervendo?`,
       `Eu: Ainda não. Pode aumentar o fogo um pouco?`, `Leo: Pronto. Nossa, está com um cheiro muito bom.`,
       `Eu: Valeu! Pode provar o molho? Precisa de mais sal?`, `Leo: Hum, talvez um pouco. Está quase perfeito.`,
       `Eu: Ótimo. Vamos comer em cinco minutos.`],
  chunks: [[`What are you doing?`, `o que você está fazendo?`], [`I'm cutting`, `estou cortando`], [`I'm trying a new recipe`, `estou testando uma receita nova`], [`Is the water boiling yet?`, `a água já está fervendo?`], [`Not yet`, `ainda não`], [`turn up the heat`, `aumentar o fogo`], [`it smells really good`, `está com um cheiro ótimo`], [`Does it need more salt?`, `precisa de mais sal?`]],
  focus: `Presente contínuo (am / is / are + -ing) é para o que está acontecendo agora: I'm cutting, the water is boiling.`,
  tasks: [`Narre em voz alta o que você está fazendo agora, com 5 frases em -ing.`, `Explique como você faz um prato simples (ovo, café, miojo).`] },

{ d: 37, title: `Moving to a new place`, pt: `Mudando de casa`, lvl: 'A2', review: true,
  en: [`Last month, I was looking for a new apartment. My budget was small, but I found a nice one close to the subway. It comes with a fridge and a stove, and it gets a lot of sunlight.`,
       `There's a bakery on my street and there are two restaurants near my building. On my first night, I went to one of them and said, “I'll have the chicken, and could I have the sauce on the side?”`,
       `The next day, I bought some new clothes. The jeans were too tight, so I returned them and got an exchange.`,
       `Now I'm cooking dinner in my new kitchen. It smells really good, and I'm happy here.`],
  tr: [`Mês passado, eu estava procurando um apartamento novo. Meu orçamento era pequeno, mas achei um legal perto do metrô. Vem com geladeira e fogão, e bate bastante sol.`,
       `Tem uma padaria na minha rua e tem dois restaurantes perto do meu prédio. Na primeira noite, fui num deles e disse: “Vou querer o frango, e pode trazer o molho à parte?”`,
       `No dia seguinte, comprei umas roupas novas. A calça jeans estava apertada demais, então devolvi e troquei.`,
       `Agora estou fazendo o jantar na minha cozinha nova. Está com um cheiro ótimo, e estou feliz aqui.`],
  chunks: [[`I was looking for`, `eu estava procurando`], [`close to the subway`, `perto do metrô`], [`It comes with`, `vem com`], [`There's a bakery`, `tem uma padaria`], [`I'll have`, `vou querer`], [`too tight`, `apertado demais`], [`got an exchange`, `consegui uma troca`], [`It smells really good`, `está com um cheiro ótimo`]],
  focus: `Revisão: dias 31 a 36. Este texto mistura passado, presente e presente contínuo, como numa conversa de verdade.`,
  tasks: [`Grave 2 minutos descrevendo a sua casa e o seu bairro.`, `Conte a última compra que você fez, do começo ao fim.`] },

{ d: 38, title: `My family`, pt: `Minha família`, lvl: 'A2',
  en: [`I come from a big family. My dad is a mechanic, and my mom is a teacher. They've been married for thirty years.`,
       `I have an older sister and a younger brother. My sister looks like my mom. She's tall, with long dark hair. My brother looks more like my dad, and he's really funny.`,
       `My sister is married and has a little boy. My nephew is four years old, and he never stops talking.`,
       `We don't live in the same city anymore, but we have a family group chat. We send messages and silly pictures every day.`],
  tr: [`Venho de uma família grande. Meu pai é mecânico e minha mãe é professora. Eles são casados há trinta anos.`,
       `Tenho uma irmã mais velha e um irmão mais novo. Minha irmã é parecida com a minha mãe. Ela é alta, com cabelo comprido e escuro. Meu irmão parece mais com o meu pai, e ele é muito engraçado.`,
       `Minha irmã é casada e tem um menininho. Meu sobrinho tem quatro anos e não para de falar.`,
       `Não moramos mais na mesma cidade, mas temos um grupo da família. Mandamos mensagens e fotos bobas todo dia.`],
  chunks: [[`I come from a big family`, `venho de uma família grande`], [`They've been married for`, `são casados há`], [`an older sister`, `uma irmã mais velha`], [`a younger brother`, `um irmão mais novo`], [`looks like`, `é parecido com`], [`he never stops talking`, `não para de falar`], [`anymore`, `mais (não … mais)`], [`group chat`, `grupo (de mensagens)`]],
  focus: `“Look like” = parecer fisicamente: she looks like my mom. Profissão leva “a/an”: my dad is a mechanic, she's an engineer.`,
  tasks: [`Apresente a sua família: quem são, o que fazem e com quem cada um parece.`, `Descreva uma pessoa fisicamente em 3 frases.`] },

{ d: 39, title: `What is he like?`, pt: `Como ele é?`, lvl: 'A2',
  en: [`Nina: I met your friend Carlos yesterday. What's he like?`, `Me: He's really outgoing. He talks to everyone, and he's always making jokes.`,
       `Nina: And your other friend, Pedro? He seemed kind of quiet.`, `Me: Yeah, Pedro is shy at first, but once you get to know him, he's super easygoing.`,
       `Nina: That's good. I'm a bit shy too.`, `Me: Really? You don't look shy at all!`,
       `Nina: I'm better with people now. But I still get nervous with big groups.`, `Me: Same here. Small groups are more my thing.`],
  tr: [`Nina: Conheci seu amigo Carlos ontem. Como ele é?`, `Eu: Ele é muito extrovertido. Conversa com todo mundo e está sempre fazendo piada.`,
       `Nina: E seu outro amigo, o Pedro? Ele parecia meio quieto.`, `Eu: É, o Pedro é tímido no começo, mas quando você conhece ele melhor, ele é super tranquilo.`,
       `Nina: Que bom. Eu também sou meio tímida.`, `Eu: Sério? Você não parece nada tímida!`,
       `Nina: Hoje estou melhor com pessoas. Mas ainda fico nervosa com grupos grandes.`, `Eu: Eu também. Grupos pequenos são mais a minha praia.`],
  chunks: [[`What's he like?`, `como ele é? (personalidade)`], [`He's really outgoing`, `ele é muito extrovertido`], [`making jokes`, `fazendo piada`], [`shy at first`, `tímido no começo`], [`once you get to know him`, `quando você conhece ele melhor`], [`easygoing`, `tranquilo / de boa`], [`at all`, `nem um pouco (com negativa)`], [`Same here`, `eu também`], [`more my thing`, `mais a minha praia`]],
  focus: `“What's he like?” pergunta a personalidade. “What does he look like?” pergunta a aparência. “How is he?” pergunta se ele está bem.`,
  tasks: [`Descreva a personalidade de 3 pessoas que você conhece.`, `Como você é? Use 3 adjetivos e dê um exemplo de cada.`] },

{ d: 40, title: `A birthday party`, pt: `Uma festa de aniversário`, lvl: 'A2',
  en: [`Last Saturday was my friend Bia's birthday. She invited a few friends to her place for a small party.`,
       `I didn't know what to get her, so I asked her sister for ideas. In the end, I bought her a book and a nice card.`,
       `When I arrived, I said, “Happy birthday! This is for you.” She opened it and said, “Oh, you shouldn't have! I love it.”`,
       `We ate pizza, sang “Happy Birthday,” and played some games. I stayed until midnight. Before I left, I said, “Thanks for having me. It was a great party!”`],
  tr: [`Sábado passado foi aniversário da minha amiga Bia. Ela convidou alguns amigos para a casa dela para uma festinha.`,
       `Eu não sabia o que dar para ela, então pedi ideias para a irmã dela. No fim, comprei um livro e um cartão bonito.`,
       `Quando cheguei, eu disse: “Feliz aniversário! Isso é pra você.” Ela abriu e disse: “Ah, não precisava! Amei.”`,
       `Comemos pizza, cantamos parabéns e jogamos uns jogos. Fiquei até meia-noite. Antes de ir embora, eu disse: “Obrigado por me receber. Foi uma festa ótima!”`],
  chunks: [[`She invited a few friends`, `ela convidou alguns amigos`], [`to her place`, `para a casa dela`], [`I didn't know what to get her`, `não sabia o que dar pra ela`], [`In the end`, `no fim`], [`This is for you`, `isso é pra você`], [`you shouldn't have`, `não precisava`], [`I love it`, `amei`], [`Thanks for having me`, `obrigado por me receber`]],
  focus: `“Get” de novo: “get someone something” = comprar/dar algo para alguém. What did you get her? I got her a book.`,
  tasks: [`Conte o último aniversário que você foi: o que deu de presente e o que fizeram.`, `Treine as frases de chegar e de ir embora de uma festa.`] },

{ d: 41, title: `Meeting new people`, pt: `Conhecendo gente nova`, lvl: 'A2',
  en: [`Sam: Hi, I don't think we've met. I'm Sam.`, `Me: Nice to meet you, Sam. I'm Lucas.`, `Sam: So, how do you know Bia?`,
       `Me: We used to work together. What about you?`, `Sam: We go to the same gym. So, what do you do, Lucas?`,
       `Me: I work in IT. I help companies with their business systems. And you?`, `Sam: I'm a nurse. It's tiring, but I love it.`,
       `Me: That's awesome. Do you live around here?`, `Sam: Yeah, just a few blocks away. Hey, it was great talking to you.`,
       `Me: You too! See you around.`],
  tr: [`Sam: Oi, acho que a gente não se conhece. Sou o Sam.`, `Eu: Prazer, Sam. Sou o Lucas.`, `Sam: E aí, de onde você conhece a Bia?`,
       `Eu: A gente trabalhava junto. E você?`, `Sam: Vamos na mesma academia. E o que você faz, Lucas?`,
       `Eu: Trabalho com TI. Ajudo empresas com os sistemas delas. E você?`, `Sam: Sou enfermeiro. É cansativo, mas eu amo.`,
       `Eu: Que demais. Você mora aqui perto?`, `Sam: Sim, a poucas quadras. Ei, foi ótimo conversar com você.`,
       `Eu: Igualmente! A gente se vê por aí.`],
  chunks: [[`I don't think we've met`, `acho que a gente não se conhece`], [`how do you know`, `de onde você conhece…?`], [`We used to work together`, `a gente trabalhava junto`], [`what do you do`, `o que você faz? (profissão)`], [`I work in IT`, `trabalho com TI`], [`Do you live around here?`, `mora aqui perto?`], [`a few blocks away`, `a poucas quadras`], [`it was great talking to you`, `foi ótimo conversar com você`], [`See you around`, `a gente se vê por aí`]],
  focus: `“What do you do?” pergunta a profissão. “Used to” = algo que fazia antes e não faz mais: we used to work together.`,
  tasks: [`Responda: “What do you do?” e “How do you know [nome]?”.`, `Diga 2 coisas que você costumava fazer e não faz mais: “I used to…”.`] },

{ d: 42, title: `Can you do me a favor?`, pt: `Pode me fazer um favor?`, lvl: 'A2',
  en: [`Me: Hey, Ana, can you do me a favor?`, `Ana: Sure, what do you need?`, `Me: I'm traveling next weekend. Could you feed my cat on Saturday and Sunday?`,
       `Ana: Of course. No problem at all.`, `Me: Thank you so much! I'll leave the key with the doorman.`, `Ana: Perfect. Does he need anything else?`,
       `Me: Just fresh water and food. And if you don't mind, could you water the plants too?`, `Ana: Sure, I can do that.`,
       `Me: You're the best. I owe you one!`, `Ana: Don't worry about it. That's what friends are for.`],
  tr: [`Eu: Ei, Ana, pode me fazer um favor?`, `Ana: Claro, do que você precisa?`, `Eu: Vou viajar no fim de semana que vem. Você poderia dar comida pro meu gato no sábado e no domingo?`,
       `Ana: Claro. Sem problema nenhum.`, `Eu: Muito obrigado! Vou deixar a chave com o porteiro.`, `Ana: Perfeito. Ele precisa de mais alguma coisa?`,
       `Eu: Só água fresca e comida. E, se não se importar, poderia regar as plantas também?`, `Ana: Claro, posso fazer isso.`,
       `Eu: Você é demais. Fico te devendo uma!`, `Ana: Imagina. Amigo é pra essas coisas.`],
  chunks: [[`can you do me a favor?`, `pode me fazer um favor?`], [`what do you need?`, `do que você precisa?`], [`Could you`, `você poderia…?`], [`No problem at all`, `sem problema nenhum`], [`if you don't mind`, `se não se importar`], [`I can do that`, `posso fazer isso`], [`I owe you one`, `fico te devendo uma`], [`Don't worry about it`, `imagina / não se preocupe`], [`That's what friends are for`, `amigo é pra essas coisas`]],
  focus: `“Could you…?” é mais educado que “Can you…?”. Use “could” com quem você não conhece bem ou quando pede algo grande.`,
  tasks: [`Peça 3 favores diferentes, um com “Can you”, um com “Could you” e um com “if you don't mind”.`, `Agradeça de 3 jeitos: Thanks a lot, I owe you one, You're the best.`] },

{ d: 43, title: `Saying sorry`, pt: `Pedindo desculpas`, lvl: 'A2',
  en: [`Last week, I forgot my friend Mia's birthday. I felt terrible when I saw the pictures of her party.`,
       `I called her and said, “Mia, I'm really sorry. I completely forgot. It was my fault.”`,
       `At first, she was a little upset. She said, “It's okay, but I was waiting for your message.”`,
       `I said, “I know. That's on me. Let me make it up to you. Can I take you out for lunch this weekend?”`,
       `She laughed and said, “Fine, you're forgiven. But you're paying!” Now I have a reminder on my phone for every birthday.`],
  tr: [`Semana passada, esqueci o aniversário da minha amiga Mia. Me senti péssimo quando vi as fotos da festa dela.`,
       `Liguei para ela e disse: “Mia, me desculpa mesmo. Esqueci completamente. A culpa foi minha.”`,
       `No começo, ela ficou um pouco chateada. Ela disse: “Tudo bem, mas eu estava esperando sua mensagem.”`,
       `Eu disse: “Eu sei. Foi mal meu. Deixa eu compensar. Posso te levar pra almoçar neste fim de semana?”`,
       `Ela riu e disse: “Tá bom, está perdoado. Mas você paga!” Agora tenho um lembrete no celular para todos os aniversários.`],
  chunks: [[`I felt terrible`, `me senti péssimo`], [`I'm really sorry`, `me desculpa mesmo`], [`I completely forgot`, `esqueci completamente`], [`It was my fault`, `a culpa foi minha`], [`a little upset`, `um pouco chateado`], [`That's on me`, `foi mal meu / é culpa minha`], [`Let me make it up to you`, `deixa eu compensar`], [`you're forgiven`, `está perdoado`]],
  focus: `Cuidado: “upset” = chateado. “Excited” = animado (não “excitado”). “Sorry” serve para desculpa e para lamentar: I'm sorry to hear that.`,
  tasks: [`Peça desculpas por chegar atrasado num encontro, e ofereça compensar.`, `Responda a um pedido de desculpas de 3 jeitos: It's okay, No worries, Don't worry about it.`] },

{ d: 44, title: `People I love`, pt: `Pessoas que eu amo`, lvl: 'A2', review: true,
  en: [`This weekend was all about people. On Saturday, I went to Bia's birthday party. I got her a book, and she said, “You shouldn't have!”`,
       `At the party, I met Sam. He asked, “How do you know Bia?” I told him we used to work together. He's really outgoing, and it was great talking to him.`,
       `On Sunday, I had lunch with my family. My nephew never stops talking, and my sister looks more like my mom every year.`,
       `Before I left, my mom asked, “Can you do me a favor? Call your grandma more often.” She's right. I owe her a call.`],
  tr: [`Este fim de semana foi todo sobre pessoas. No sábado, fui na festa de aniversário da Bia. Dei um livro para ela, e ela disse: “Não precisava!”`,
       `Na festa, conheci o Sam. Ele perguntou: “De onde você conhece a Bia?” Contei que a gente trabalhava junto. Ele é muito extrovertido, e foi ótimo conversar com ele.`,
       `No domingo, almocei com minha família. Meu sobrinho não para de falar, e minha irmã fica mais parecida com a minha mãe a cada ano.`,
       `Antes de eu ir, minha mãe perguntou: “Pode me fazer um favor? Liga mais para a sua avó.” Ela tem razão. Estou devendo uma ligação para ela.`],
  chunks: [[`was all about`, `foi todo sobre`], [`You shouldn't have`, `não precisava`], [`How do you know`, `de onde você conhece…?`], [`we used to work together`, `a gente trabalhava junto`], [`He's really outgoing`, `ele é muito extrovertido`], [`never stops talking`, `não para de falar`], [`Can you do me a favor?`, `pode me fazer um favor?`], [`more often`, `com mais frequência`]],
  focus: `Revisão: dias 38 a 43. Repare como “used to”, “looks like” e “get someone something” aparecem de novo.`,
  tasks: [`Grave 2 minutos falando das pessoas mais importantes da sua vida.`, `Compare com o seu áudio do dia 28.`] },

{ d: 45, title: `What are you up to?`, pt: `O que você está fazendo?`, lvl: 'A2',
  en: [`Dani: Hey! What are you up to?`, `Me: Not much. I'm sitting on the couch, and I'm watching a documentary about space.`,
       `Dani: Nice. Are you busy tonight?`, `Me: Kind of. I'm working on a project for my English class. What about you?`,
       `Dani: I'm waiting for my sister. She's coming over for dinner.`, `Me: Cool. What are you making?`,
       `Dani: I'm not cooking tonight. We're ordering sushi.`, `Me: Good choice! Okay, I'm going back to my project. Talk later?`,
       `Dani: Sure. Good luck with it!`],
  tr: [`Dani: Oi! O que você está aprontando?`, `Eu: Nada de mais. Estou sentado no sofá assistindo um documentário sobre o espaço.`,
       `Dani: Legal. Está ocupado hoje à noite?`, `Eu: Mais ou menos. Estou trabalhando num projeto da aula de inglês. E você?`,
       `Dani: Estou esperando minha irmã. Ela vem jantar aqui.`, `Eu: Que legal. O que você vai fazer?`,
       `Dani: Não vou cozinhar hoje. Vamos pedir sushi.`, `Eu: Boa escolha! Bom, vou voltar pro meu projeto. Falamos depois?`,
       `Dani: Claro. Boa sorte!`],
  chunks: [[`What are you up to?`, `o que você está fazendo / aprontando?`], [`Not much`, `nada de mais`], [`I'm working on`, `estou trabalhando em`], [`I'm waiting for`, `estou esperando`], [`She's coming over`, `ela vem aqui (em casa)`], [`We're ordering`, `vamos pedir`], [`I'm going back to`, `vou voltar pro`], [`Good luck with it`, `boa sorte com isso`]],
  focus: `O presente contínuo também fala de planos já combinados para logo: She's coming over for dinner. We're ordering sushi.`,
  tasks: [`Responda “What are you up to?” de verdade, agora.`, `Diga 3 planos combinados para esta semana com -ing: “I'm meeting… I'm going…”.`] },

{ d: 46, title: `Healthy habits`, pt: `Hábitos saudáveis`, lvl: 'A2',
  en: [`I'm trying to be healthier this year. I go to the gym three times a week, usually before work. I'm not a morning person, but it's the only time I have.`,
       `I almost never drink soda now, and I try to drink two liters of water a day. I still eat junk food sometimes, especially on weekends.`,
       `The hardest part is sleep. I often go to bed too late because I'm on my phone.`,
       `My doctor says I should sleep at least seven hours a night. So now I leave my phone in the living room. It's hard, but I feel much better.`],
  tr: [`Estou tentando ser mais saudável este ano. Vou à academia três vezes por semana, normalmente antes do trabalho. Não sou uma pessoa matutina, mas é o único horário que tenho.`,
       `Quase nunca tomo refrigerante agora, e tento beber dois litros de água por dia. Ainda como besteira às vezes, principalmente nos fins de semana.`,
       `A parte mais difícil é o sono. Muitas vezes vou dormir tarde demais porque fico no celular.`,
       `Meu médico diz que eu deveria dormir pelo menos sete horas por noite. Então agora deixo o celular na sala. É difícil, mas me sinto muito melhor.`],
  chunks: [[`I'm trying to be healthier`, `estou tentando ser mais saudável`], [`three times a week`, `três vezes por semana`], [`I'm not a morning person`, `não sou uma pessoa matutina`], [`I almost never`, `quase nunca`], [`junk food`, `besteira / porcaria`], [`The hardest part is`, `a parte mais difícil é`], [`I'm on my phone`, `fico no celular`], [`I should`, `eu deveria`], [`at least`, `pelo menos`]],
  focus: `Frequência: always, usually, often, sometimes, almost never, never. Ficam antes do verbo (I often go), mas depois do to be (I'm always tired).`,
  tasks: [`Fale da sua frequência: academia, água, sono, celular. “I usually… I never…”.`, `Dê 2 conselhos de saúde com “You should…”.`] },

{ d: 47, title: `My phone and me`, pt: `Eu e meu celular`, lvl: 'A2',
  en: [`I have to be honest: I spend too much time on my phone. Last week, my screen time was five hours a day!`,
       `Most of the time, I'm scrolling through videos. I open the app for “just five minutes,” and suddenly it's been an hour.`,
       `Social media isn't all bad. I follow some English teachers, and I learn new expressions every day. I also keep in touch with friends who live far away.`,
       `But I want to cut down. I turned off most notifications, and I'm trying to put my phone away during meals. So far, so good.`],
  tr: [`Preciso ser sincero: passo tempo demais no celular. Semana passada, meu tempo de tela foi de cinco horas por dia!`,
       `Na maior parte do tempo, estou rolando vídeos. Abro o app “só cinco minutinhos” e, de repente, já passou uma hora.`,
       `Rede social não é só coisa ruim. Sigo alguns professores de inglês e aprendo expressões novas todo dia. Também mantenho contato com amigos que moram longe.`,
       `Mas quero diminuir. Desliguei a maioria das notificações e estou tentando guardar o celular durante as refeições. Até agora, tudo certo.`],
  chunks: [[`I have to be honest`, `preciso ser sincero`], [`I spend too much time on my phone`, `passo tempo demais no celular`], [`Most of the time`, `na maior parte do tempo`], [`scrolling through`, `rolando (a tela)`], [`suddenly`, `de repente`], [`keep in touch with`, `manter contato com`], [`cut down`, `diminuir`], [`turned off`, `desliguei`], [`put my phone away`, `guardar o celular`], [`So far, so good`, `até agora, tudo certo`]],
  focus: `“Spend” = gastar dinheiro E tempo: I spend two hours on my phone. Phrasal verbs úteis: turn off (desligar), turn on (ligar), put away (guardar).`,
  tasks: [`Veja o seu tempo de tela e conte em inglês quanto e com o quê.`, `Diga uma coisa boa e uma ruim das redes sociais para você.`] },

{ d: 48, title: `What are you into?`, pt: `Do que você curte?`, lvl: 'A2',
  en: [`Mel: So, what do you do in your free time?`, `Me: I'm really into video games. I've been playing the same game for two years.`,
       `Mel: Wow! What kind of games do you like?`, `Me: Mostly strategy games. And lately I've been getting into photography too.`,
       `Mel: That's cool. Do you have a good camera?`, `Me: Not yet. I just use my phone for now. What about you? What are you into?`,
       `Mel: I'm a big fan of hiking. I go almost every weekend.`, `Me: I've always wanted to try it. Can I join you sometime?`,
       `Mel: Of course! Next time we go, I'll let you know.`],
  tr: [`Mel: E aí, o que você faz no tempo livre?`, `Eu: Curto muito videogame. Jogo o mesmo jogo há dois anos.`,
       `Mel: Nossa! Que tipo de jogo você gosta?`, `Eu: Principalmente de estratégia. E ultimamente comecei a curtir fotografia também.`,
       `Mel: Que legal. Você tem uma câmera boa?`, `Eu: Ainda não. Uso só o celular por enquanto. E você? Do que você curte?`,
       `Mel: Sou muito fã de trilha. Vou quase todo fim de semana.`, `Eu: Sempre quis experimentar. Posso ir com vocês algum dia?`,
       `Mel: Claro! Na próxima vez que a gente for, eu te aviso.`],
  chunks: [[`in your free time`, `no tempo livre`], [`I'm really into`, `eu curto muito`], [`I've been playing`, `jogo há… (até hoje)`], [`What kind of`, `que tipo de`], [`lately`, `ultimamente`], [`getting into`, `começando a curtir`], [`I'm a big fan of`, `sou muito fã de`], [`I've always wanted to`, `sempre quis`], [`Can I join you sometime?`, `posso ir junto algum dia?`]],
  focus: `“I'm into…” é o jeito mais natural de falar do que você gosta muito. “I've been playing for two years” = jogo há dois anos e continuo.`,
  tasks: [`Fale de 2 hobbies seus: o que é, há quanto tempo, por que você curte.`, `Diga algo que você sempre quis fazer: “I've always wanted to…”.`] },

{ d: 49, title: `The weather`, pt: `O tempo`, lvl: 'A2',
  en: [`People in English-speaking countries talk about the weather all the time. It's the easiest way to start a conversation.`,
       `“It's freezing today!” means it's very cold. “It's boiling” or “It's so hot” means the opposite. When it's raining a lot, people say, “It's pouring.”`,
       `In my city, summer is hot and humid. It rains almost every afternoon, so I always carry an umbrella.`,
       `Winter is mild, but sometimes it gets a little chilly at night. I check the forecast every morning. Today it says it's going to be sunny, with a high of thirty degrees.`],
  tr: [`As pessoas em países de língua inglesa falam do tempo o tempo todo. É o jeito mais fácil de começar uma conversa.`,
       `“It's freezing today!” significa que está muito frio. “It's boiling” ou “It's so hot” significa o contrário. Quando está chovendo muito, as pessoas dizem “It's pouring” (está caindo um temporal).`,
       `Na minha cidade, o verão é quente e úmido. Chove quase toda tarde, então sempre carrego um guarda-chuva.`,
       `O inverno é ameno, mas às vezes fica um pouco frio à noite. Vejo a previsão toda manhã. Hoje ela diz que vai fazer sol, com máxima de trinta graus.`],
  chunks: [[`talk about the weather`, `falar do tempo`], [`the easiest way to`, `o jeito mais fácil de`], [`It's freezing`, `está um gelo`], [`It's pouring`, `está caindo um temporal`], [`hot and humid`, `quente e úmido`], [`it gets a little chilly`, `fica um pouco frio`], [`the forecast`, `a previsão do tempo`], [`it's going to be sunny`, `vai fazer sol`]],
  focus: `Tempo sempre começa com “it”: It's hot, it's raining, it's going to rain. Nunca “Is hot” sozinho, sem o “it”.`,
  tasks: [`Descreva o tempo de hoje e a previsão de amanhã.`, `Comece uma conversa com um estranho falando do tempo.`] },

{ d: 50, title: `Talking about soccer`, pt: `Falando de futebol`, lvl: 'A2',
  en: [`Jake: Did you watch the game last night?`, `Me: Of course! What a game! I couldn't believe that last goal.`,
       `Jake: Me neither. Who do you root for, by the way?`, `Me: I'm a Flamengo fan. It's a big team in Brazil. What about you?`,
       `Jake: I don't really follow soccer, but I love the World Cup.`, `Me: Everybody loves the World Cup! Who do you think is going to win next time?`,
       `Jake: Honestly, no idea. Maybe Argentina again?`, `Me: Please, don't say that! I hope it's Brazil.`, `Jake: Ha! We'll see.`],
  tr: [`Jake: Você assistiu o jogo ontem à noite?`, `Eu: Claro! Que jogo! Não acreditei naquele último gol.`,
       `Jake: Nem eu. Aliás, pra que time você torce?`, `Eu: Sou flamenguista. É um time grande no Brasil. E você?`,
       `Jake: Eu não acompanho muito futebol, mas amo a Copa do Mundo.`, `Eu: Todo mundo ama a Copa! Quem você acha que vai ganhar a próxima?`,
       `Jake: Sinceramente, não faço ideia. Talvez a Argentina de novo?`, `Eu: Por favor, não fala isso! Espero que seja o Brasil.`, `Jake: Ha! Vamos ver.`],
  chunks: [[`Did you watch the game`, `você viu o jogo?`], [`What a game!`, `que jogo!`], [`I couldn't believe`, `não acreditei`], [`Me neither`, `nem eu`], [`Who do you root for`, `pra quem você torce?`], [`by the way`, `aliás / a propósito`], [`I don't really follow`, `não acompanho muito`], [`no idea`, `não faço ideia`], [`We'll see`, `vamos ver`]],
  focus: `“Me too” concorda com frase positiva. “Me neither” concorda com frase negativa: I can't believe it. Me neither.`,
  tasks: [`Fale do seu time ou do seu esporte favorito em 4 frases.`, `Treine “Me too” e “Me neither” respondendo a 4 frases.`] },

{ d: 51, title: `My life these days`, pt: `Minha vida ultimamente`, lvl: 'A2', review: true,
  en: [`These days, I'm trying to be healthier. I go to the gym three times a week, and I almost never drink soda.`,
       `I'm also working on my screen time. I turned off most notifications, and I put my phone away during meals. So far, so good.`,
       `In my free time, I'm really into video games, and lately I've been getting into photography too.`,
       `This week the weather is crazy. Yesterday it was pouring, and today it's boiling. And on Sunday I'm watching the big game with my friends. We'll see who wins!`],
  tr: [`Ultimamente, estou tentando ser mais saudável. Vou à academia três vezes por semana e quase nunca tomo refrigerante.`,
       `Também estou cuidando do meu tempo de tela. Desliguei a maioria das notificações e guardo o celular durante as refeições. Até agora, tudo certo.`,
       `No tempo livre, curto muito videogame, e ultimamente comecei a curtir fotografia também.`,
       `Esta semana o tempo está maluco. Ontem caiu um temporal, e hoje está um calor de matar. E no domingo vou ver o jogão com meus amigos. Vamos ver quem ganha!`],
  chunks: [[`These days`, `ultimamente / hoje em dia`], [`three times a week`, `três vezes por semana`], [`I'm also working on`, `também estou trabalhando em`], [`put my phone away`, `guardo o celular`], [`So far, so good`, `até agora, tudo certo`], [`I'm really into`, `curto muito`], [`it was pouring`, `caiu um temporal`], [`We'll see`, `vamos ver`]],
  focus: `Revisão: dias 45 a 50. Simples para hábitos (I go to the gym), contínuo para agora e fase atual (I'm trying, I'm working on).`,
  tasks: [`Grave 2 minutos: “My life these days”.`, `Separe no seu áudio uma frase de hábito e uma de fase atual. Usou certo?`] },

{ d: 52, title: `At the airport`, pt: `No aeroporto`, lvl: 'A2',
  en: [`Agent: Good morning. Where are you flying today?`, `Me: To Miami. Here's my passport.`, `Agent: Thank you. Are you checking any bags?`,
       `Me: Just one. And this backpack is my carry-on.`, `Agent: Okay. Would you like a window or an aisle seat?`,
       `Me: Window, please.`, `Agent: Here's your boarding pass. Boarding starts at nine forty, at gate twelve.`,
       `Me: Sorry, which gate?`, `Agent: Gate twelve. Go through security and turn right.`, `Me: Great, thanks. Have a good one!`],
  tr: [`Atendente: Bom dia. Para onde você vai voar hoje?`, `Eu: Para Miami. Aqui está meu passaporte.`, `Atendente: Obrigada. Vai despachar alguma mala?`,
       `Eu: Só uma. E esta mochila é minha bagagem de mão.`, `Atendente: Certo. Prefere janela ou corredor?`,
       `Eu: Janela, por favor.`, `Atendente: Aqui está seu cartão de embarque. O embarque começa às nove e quarenta, no portão doze.`,
       `Eu: Desculpa, qual portão?`, `Atendente: Portão doze. Passe pela segurança e vire à direita.`, `Eu: Ótimo, obrigado. Bom dia pra você!`],
  chunks: [[`Where are you flying today?`, `para onde vai voar hoje?`], [`Here's my passport`, `aqui está meu passaporte`], [`Are you checking any bags?`, `vai despachar mala?`], [`carry-on`, `bagagem de mão`], [`a window or an aisle seat`, `janela ou corredor`], [`boarding pass`, `cartão de embarque`], [`Boarding starts at`, `o embarque começa às`], [`Go through security`, `passe pela segurança`], [`Have a good one`, `tenha um bom dia`]],
  focus: `“Check” no aeroporto = despachar: check a bag. “Check in” = fazer o check-in. “Sorry, which gate?” confirma só a parte que você não pegou.`,
  tasks: [`Faça o check-in de uma viagem imaginária para onde você quiser.`, `Confirme 3 informações com “Sorry, which…? / what time…?”.`] },

{ d: 53, title: `At the hotel`, pt: `No hotel`, lvl: 'A2',
  en: [`Receptionist: Hi, welcome! Checking in?`, `Me: Yes. I have a reservation under the name Lucas Silva.`,
       `Receptionist: Let me see… Yes, three nights, a double room. Can I see your ID and a credit card, please?`, `Me: Sure, here you go. Is breakfast included?`,
       `Receptionist: Yes, it's served from six to ten in the lobby. Here's your key card. You're in room 504.`, `Me: Thanks. What's the Wi-Fi password?`,
       `Receptionist: It's on the back of the card. And checkout is at noon.`, `Me: Is it possible to leave my bags here after checkout?`,
       `Receptionist: Absolutely. Enjoy your stay!`],
  tr: [`Recepcionista: Oi, seja bem-vindo! Fazendo check-in?`, `Eu: Sim. Tenho uma reserva no nome de Lucas Silva.`,
       `Recepcionista: Deixa eu ver… Sim, três noites, quarto de casal. Posso ver seu documento e um cartão de crédito, por favor?`, `Eu: Claro, aqui estão. O café da manhã está incluso?`,
       `Recepcionista: Sim, é servido das seis às dez no saguão. Aqui está seu cartão-chave. Você está no quarto 504.`, `Eu: Obrigado. Qual é a senha do Wi-Fi?`,
       `Recepcionista: Está no verso do cartão. E o check-out é ao meio-dia.`, `Eu: É possível deixar minhas malas aqui depois do check-out?`,
       `Recepcionista: Com certeza. Aproveite a estadia!`],
  chunks: [[`I have a reservation under the name`, `tenho uma reserva no nome de`], [`a double room`, `quarto de casal`], [`here you go`, `aqui está`], [`Is breakfast included?`, `o café está incluso?`], [`What's the Wi-Fi password?`, `qual é a senha do Wi-Fi?`], [`checkout is at noon`, `o check-out é ao meio-dia`], [`Is it possible to`, `é possível…?`], [`Enjoy your stay`, `aproveite a estadia`]],
  focus: `“Is it possible to…?” e “Is … included?” resolvem quase tudo em hotel. Reserva “under the name” = no nome de.`,
  tasks: [`Faça o check-in e pergunte 3 coisas: café, Wi-Fi, horário do check-out.`, `Reclame de um problema no quarto: “The air conditioning isn't working.”`] },

{ d: 54, title: `Taking a ride`, pt: `Pegando um carro`, lvl: 'A2',
  en: [`Driver: Hi! Lucas?`, `Me: Yes, that's me. Hi!`, `Driver: Going to the Art Museum, right?`,
       `Me: That's right. How long does it take to get there?`, `Driver: Usually fifteen minutes, but there's a lot of traffic today. Maybe twenty-five.`,
       `Me: No problem. Is it okay if I open the window a little?`, `Driver: Sure, go ahead. Is this your first time in the city?`,
       `Me: Yes, I got here yesterday. Any tips?`, `Driver: Try the food trucks downtown. They're cheap and really good.`,
       `Me: Thanks for the tip! You can drop me off at the corner.`],
  tr: [`Motorista: Oi! Lucas?`, `Eu: Sim, sou eu. Oi!`, `Motorista: Indo para o Museu de Arte, certo?`,
       `Eu: Isso. Quanto tempo leva para chegar lá?`, `Motorista: Normalmente quinze minutos, mas o trânsito está pesado hoje. Talvez vinte e cinco.`,
       `Eu: Sem problema. Tudo bem se eu abrir um pouco a janela?`, `Motorista: Claro, pode abrir. É sua primeira vez na cidade?`,
       `Eu: Sim, cheguei ontem. Alguma dica?`, `Motorista: Experimente os food trucks do centro. São baratos e muito bons.`,
       `Eu: Valeu pela dica! Pode me deixar na esquina.`],
  chunks: [[`that's me`, `sou eu`], [`That's right`, `isso / correto`], [`How long does it take to get there?`, `quanto tempo leva pra chegar?`], [`there's a lot of traffic`, `o trânsito está pesado`], [`Is it okay if I`, `tudo bem se eu…?`], [`go ahead`, `pode ir / fique à vontade`], [`Any tips?`, `alguma dica?`], [`Thanks for the tip`, `valeu pela dica`], [`drop me off`, `me deixar (em algum lugar)`]],
  focus: `“How long does it take?” pergunta duração. Resposta: It takes twenty minutes. “Drop off” = deixar; “pick up” = buscar.`,
  tasks: [`Diga quanto tempo leva da sua casa até 3 lugares: “It takes…”.`, `Peça para o motorista te deixar num lugar específico.`] },

{ d: 55, title: `My bag didn't arrive`, pt: `Minha mala não chegou`, lvl: 'A2',
  en: [`On my trip to Chicago, everything went wrong on the first day. First, my flight was delayed for three hours.`,
       `When I finally landed, I waited at baggage claim for forty minutes, but my suitcase never showed up.`,
       `I went to the airline desk and said, “Hi, my bag didn't arrive. What should I do?” The agent asked me to fill out a form and describe the suitcase.`,
       `She said, “Don't worry. It's probably on the next flight. We'll deliver it to your hotel.”`,
       `I bought a toothbrush and a T-shirt and tried to stay calm. The next morning, my bag was at the front desk. What a relief!`],
  tr: [`Na minha viagem para Chicago, deu tudo errado no primeiro dia. Primeiro, meu voo atrasou três horas.`,
       `Quando finalmente pousei, esperei na esteira de bagagens por quarenta minutos, mas minha mala nunca apareceu.`,
       `Fui ao balcão da companhia aérea e disse: “Oi, minha mala não chegou. O que eu devo fazer?” A atendente me pediu para preencher um formulário e descrever a mala.`,
       `Ela disse: “Não se preocupe. Provavelmente está no próximo voo. Vamos entregar no seu hotel.”`,
       `Comprei uma escova de dentes e uma camiseta e tentei ficar calmo. Na manhã seguinte, minha mala estava na recepção. Que alívio!`],
  chunks: [[`everything went wrong`, `deu tudo errado`], [`my flight was delayed`, `meu voo atrasou`], [`baggage claim`, `esteira / retirada de bagagem`], [`never showed up`, `nunca apareceu`], [`What should I do?`, `o que eu devo fazer?`], [`fill out a form`, `preencher um formulário`], [`stay calm`, `ficar calmo`], [`What a relief!`, `que alívio!`]],
  focus: `“Show up” = aparecer (coisa ou pessoa): he didn't show up to the meeting. “Fill out” = preencher.`,
  tasks: [`Conte um imprevisto de viagem (real ou inventado) com começo, problema e solução.`, `Pergunte o que fazer em 2 situações: “My card isn't working. What should I do?”.`] },

{ d: 56, title: `What do you recommend?`, pt: `O que você recomenda?`, lvl: 'A2',
  en: [`Me: Excuse me, I'm visiting for the weekend. What do you recommend I see?`, `Local: Well, the old town is a must. It's beautiful at night.`,
       `Me: Is it worth visiting the castle too?`, `Local: Definitely. But go early, because it gets really crowded after ten.`,
       `Me: Good to know. And where's a good place to eat around here?`, `Local: There's a small place on Green Street. It doesn't look like much, but the food is amazing.`,
       `Me: Is it expensive?`, `Local: Not at all. It's pretty cheap, actually.`, `Me: Perfect. Thank you so much!`, `Local: My pleasure. Enjoy your trip!`],
  tr: [`Eu: Com licença, estou visitando no fim de semana. O que você recomenda que eu veja?`, `Morador: Bom, a cidade velha é imperdível. É linda à noite.`,
       `Eu: Vale a pena visitar o castelo também?`, `Morador: Com certeza. Mas vá cedo, porque fica muito cheio depois das dez.`,
       `Eu: Bom saber. E onde tem um lugar bom pra comer aqui perto?`, `Morador: Tem um lugarzinho na Green Street. Não parece grande coisa, mas a comida é incrível.`,
       `Eu: É caro?`, `Morador: Nem um pouco. Na verdade, é bem barato.`, `Eu: Perfeito. Muito obrigado!`, `Morador: O prazer é meu. Aproveite a viagem!`],
  chunks: [[`What do you recommend`, `o que você recomenda?`], [`is a must`, `é imperdível`], [`Is it worth visiting`, `vale a pena visitar?`], [`Definitely`, `com certeza`], [`Good to know`, `bom saber`], [`a good place to eat around here`, `um lugar bom pra comer aqui perto`], [`It doesn't look like much`, `não parece grande coisa`], [`pretty cheap`, `bem barato`], [`My pleasure`, `o prazer é meu`]],
  focus: `“Is it worth…?” = vale a pena…? Responde com “It's (not) worth it”. “Pretty” antes de adjetivo = bem / bastante: pretty good, pretty cheap.`,
  tasks: [`Recomende 3 lugares da sua cidade para um turista, com um motivo cada.`, `Diga algo que vale e algo que não vale a pena: “It's worth… / It's not worth…”.`] },

{ d: 57, title: `Comparing two cities`, pt: `Comparando duas cidades`, lvl: 'A2',
  en: [`I lived in São Paulo for two years, and now I live in Recife. People always ask me which one is better.`,
       `São Paulo is much bigger and busier than Recife. There are more jobs and more things to do, but the traffic is worse and life is more expensive.`,
       `Recife is smaller and more relaxed. The weather is hotter, and the beaches are much better. People are also friendlier, in my opinion.`,
       `For my career, São Paulo was the best place. But for my quality of life, Recife wins. It's the most beautiful city I've ever lived in.`],
  tr: [`Morei em São Paulo por dois anos, e agora moro em Recife. As pessoas sempre me perguntam qual é melhor.`,
       `São Paulo é muito maior e mais agitada que Recife. Tem mais empregos e mais coisas pra fazer, mas o trânsito é pior e a vida é mais cara.`,
       `Recife é menor e mais tranquila. O clima é mais quente, e as praias são muito melhores. As pessoas também são mais simpáticas, na minha opinião.`,
       `Para a minha carreira, São Paulo foi o melhor lugar. Mas para a minha qualidade de vida, Recife ganha. É a cidade mais bonita em que eu já morei.`],
  chunks: [[`which one is better`, `qual é melhor`], [`much bigger and busier than`, `muito maior e mais agitada que`], [`more things to do`, `mais coisas pra fazer`], [`the traffic is worse`, `o trânsito é pior`], [`more expensive`, `mais caro`], [`smaller and more relaxed`, `menor e mais tranquila`], [`the best place`, `o melhor lugar`], [`I've ever lived in`, `em que eu já morei`]],
  focus: `Palavras curtas ganham -er / -est: bigger, the biggest. Palavras longas usam more / most: more expensive, the most beautiful. Irregulares: good → better → the best; bad → worse → the worst.`,
  tasks: [`Compare duas cidades, dois empregos ou dois times com 5 frases.`, `Diga “the best… I've ever…” sobre um filme, uma comida e uma viagem.`] },

{ d: 58, title: `My first trip abroad`, pt: `Minha primeira viagem internacional`, lvl: 'A2', review: true,
  en: [`Last year, I took my first trip abroad, to Chicago. At the airport, I checked one bag and asked for a window seat. My flight was delayed, and my bag never showed up. What a start!`,
       `At the hotel, I said, “I have a reservation under the name Lucas Silva.” Breakfast was included, which was great.`,
       `The next day, my bag arrived, and I asked a local, “What do you recommend?” She said the river tour was a must, and she was right. It was definitely worth it.`,
       `Chicago is much bigger and colder than my city, but it's one of the most beautiful places I've ever visited.`],
  tr: [`No ano passado, fiz minha primeira viagem internacional, para Chicago. No aeroporto, despachei uma mala e pedi janela. Meu voo atrasou, e minha mala nunca apareceu. Que começo!`,
       `No hotel, eu disse: “Tenho uma reserva no nome de Lucas Silva.” O café da manhã estava incluso, o que foi ótimo.`,
       `No dia seguinte, minha mala chegou, e perguntei para uma moradora: “O que você recomenda?” Ela disse que o passeio pelo rio era imperdível, e ela estava certa. Valeu muito a pena.`,
       `Chicago é muito maior e mais fria que a minha cidade, mas é um dos lugares mais bonitos que eu já visitei.`],
  chunks: [[`my first trip abroad`, `minha primeira viagem internacional`], [`asked for a window seat`, `pedi janela`], [`My flight was delayed`, `meu voo atrasou`], [`never showed up`, `nunca apareceu`], [`I have a reservation under the name`, `tenho reserva no nome de`], [`was a must`, `era imperdível`], [`It was definitely worth it`, `valeu muito a pena`], [`I've ever visited`, `que eu já visitei`]],
  focus: `Revisão: dias 52 a 57. Com estes 7 textos você já consegue se virar numa viagem do começo ao fim.`,
  tasks: [`Grave 2 minutos contando uma viagem, do aeroporto à volta.`, `Compare a cidade da viagem com a sua, usando 3 comparativos.`] },

{ d: 59, title: `Phrasal verbs you hear every day`, pt: `Phrasal verbs que você ouve todo dia`, lvl: 'A2',
  en: [`Phrasal verbs are verbs with a small word after them, like “up,” “out” or “on.” Native speakers use them all the time, so you need to know the common ones.`,
       `In the morning, I get up, put on my clothes and pick up my coffee on the way to work.`,
       `At work, when I don't know something, I look it up online. If I can't find out the answer, I keep trying until I figure it out.`,
       `When I get tired of studying, I never give up. I take a break, and then I come back.`,
       `At night, I turn off the TV and look forward to the next day.`],
  tr: [`Phrasal verbs são verbos com uma palavrinha depois, como “up”, “out” ou “on”. Nativos usam eles o tempo todo, então você precisa conhecer os mais comuns.`,
       `De manhã, eu levanto, coloco a roupa e pego meu café no caminho do trabalho.`,
       `No trabalho, quando não sei algo, eu pesquiso na internet. Se não consigo descobrir a resposta, continuo tentando até entender.`,
       `Quando canso de estudar, nunca desisto. Faço uma pausa e depois volto.`,
       `À noite, desligo a TV e fico ansioso (no bom sentido) pelo dia seguinte.`],
  chunks: [[`get up`, `levantar`], [`put on`, `vestir / colocar`], [`pick up`, `pegar / buscar`], [`look it up`, `pesquisar (algo)`], [`find out`, `descobrir`], [`keep trying`, `continuar tentando`], [`figure it out`, `entender / resolver`], [`give up`, `desistir`], [`come back`, `voltar`], [`look forward to`, `esperar ansiosamente`]],
  focus: `Aprenda phrasal verbs em frases, nunca em listas soltas. “Look forward to” é usado até em e-mail formal: I look forward to hearing from you.`,
  tasks: [`Conte o seu dia usando pelo menos 6 dos phrasal verbs.`, `Faça uma frase sobre algo que você nunca vai desistir: “I'll never give up on…”.`] },

{ d: 60, title: `Two minutes about my life`, pt: `Dois minutos sobre a minha vida`, lvl: 'A2',
  en: [`This is your test for month two. Use this model, change it to your life, and talk for two minutes without reading.`,
       `I'm Lucas, and I live in a quiet neighborhood in Recife. I come from a big family. My sister looks like my mom, and my nephew never stops talking.`,
       `These days, I'm trying to be healthier. I go to the gym three times a week, and I'm cutting down on my screen time. In my free time, I'm really into video games and photography.`,
       `Last year, I took my first trip abroad. Everything went wrong on the first day, but it was definitely worth it.`,
       `Next year, I'm going to travel again, and this time I'm going to speak English with everyone.`],
  tr: [`Este é o seu teste do mês dois. Use este modelo, adapte para a sua vida e fale por dois minutos sem ler.`,
       `Sou o Lucas e moro num bairro tranquilo em Recife. Venho de uma família grande. Minha irmã é parecida com a minha mãe, e meu sobrinho não para de falar.`,
       `Ultimamente, estou tentando ser mais saudável. Vou à academia três vezes por semana e estou diminuindo o tempo de tela. No tempo livre, curto muito videogame e fotografia.`,
       `No ano passado, fiz minha primeira viagem internacional. Deu tudo errado no primeiro dia, mas valeu muito a pena.`,
       `No ano que vem, vou viajar de novo, e desta vez vou falar inglês com todo mundo.`],
  chunks: [[`I live in a quiet neighborhood`, `moro num bairro tranquilo`], [`I come from a big family`, `venho de uma família grande`], [`These days`, `ultimamente`], [`cutting down on`, `diminuindo`], [`I'm really into`, `curto muito`], [`my first trip abroad`, `minha primeira viagem internacional`], [`it was definitely worth it`, `valeu muito a pena`], [`this time`, `desta vez`]],
  focus: `Dois minutos é o dobro do teste do mês 1. Se travar, use os “filler words” do dia 29: Let me think, you know, I mean…`,
  tasks: [`Grave 2 minutos sobre a sua vida sem ler. Esse é o seu teste do mês 2.`, `Ouça o seu áudio do dia 30 e o de hoje. Anote 3 coisas que melhoraram.`] },
{ d: 61, title: `What I do at work`, pt: `O que eu faço no trabalho`, lvl: 'A2',
  en: [`People often ask me what I do, and it's not easy to explain. I work with SAP, a system that big companies use to manage sales, stock and finance.`,
       `Basically, I make sure the sales process works. When a customer places an order, the system creates a delivery and then an invoice. My job is to configure that flow and fix it when something breaks.`,
       `I spend most of my day talking to users, testing changes and writing documentation.`,
       `It can be stressful, but I like solving problems. When everything works at the end of the day, I feel proud.`],
  tr: [`As pessoas sempre me perguntam o que eu faço, e não é fácil explicar. Trabalho com SAP, um sistema que grandes empresas usam para gerenciar vendas, estoque e finanças.`,
       `Basicamente, eu garanto que o processo de vendas funcione. Quando um cliente faz um pedido, o sistema cria uma remessa e depois uma fatura. Meu trabalho é configurar esse fluxo e consertar quando algo quebra.`,
       `Passo a maior parte do dia conversando com usuários, testando mudanças e escrevendo documentação.`,
       `Pode ser estressante, mas eu gosto de resolver problemas. Quando tudo funciona no fim do dia, sinto orgulho.`],
  chunks: [[`what I do`, `o que eu faço`], [`it's not easy to explain`, `não é fácil explicar`], [`Basically`, `basicamente`], [`I make sure`, `eu garanto que`], [`places an order`, `faz um pedido`], [`when something breaks`, `quando algo quebra`], [`I spend most of my day`, `passo a maior parte do dia`], [`It can be stressful`, `pode ser estressante`], [`I like solving problems`, `gosto de resolver problemas`]],
  focus: `“Basically…” e “My job is to…” são as duas melhores portas de entrada para explicar o seu trabalho de forma simples.`,
  tasks: [`Explique o seu trabalho (ou curso) em 4 frases, como se fosse para alguém de fora da área.`, `Diga o que você faz na maior parte do dia: “I spend most of my day…”.`] },

{ d: 62, title: `The system is down`, pt: `O sistema caiu`, lvl: 'A2',
  en: [`User: Hi, sorry to bother you. I can't create any invoices. I keep getting an error message.`, `Me: No problem. What does the error say?`,
       `User: It says “Pricing error.” It started about an hour ago.`, `Me: Okay. Is it happening with all customers or just one?`,
       `User: I think it's all of them.`, `Me: Got it. Can you send me a screenshot? I'll look into it right away.`,
       `Later…`, `Me: I found the problem. A price condition expired yesterday. I fixed it, so it should work now. Can you try again?`,
       `User: It worked! Thank you so much.`, `Me: Anytime. Let me know if it happens again.`],
  tr: [`Usuária: Oi, desculpa incomodar. Não consigo criar nenhuma fatura. Fica aparecendo uma mensagem de erro.`, `Eu: Sem problema. O que diz o erro?`,
       `Usuária: Diz “Erro de preço”. Começou há mais ou menos uma hora.`, `Eu: Certo. Está acontecendo com todos os clientes ou só um?`,
       `Usuária: Acho que com todos.`, `Eu: Entendi. Pode me mandar um print? Vou verificar agora mesmo.`,
       `Mais tarde…`, `Eu: Achei o problema. Uma condição de preço venceu ontem. Corrigi, então deve funcionar agora. Pode tentar de novo?`,
       `Usuária: Funcionou! Muito obrigada.`, `Eu: Sempre que precisar. Me avisa se acontecer de novo.`],
  chunks: [[`sorry to bother you`, `desculpa incomodar`], [`I keep getting an error message`, `fica dando mensagem de erro`], [`What does the error say?`, `o que diz o erro?`], [`It started about an hour ago`, `começou há uma hora`], [`Is it happening with`, `está acontecendo com…?`], [`I'll look into it right away`, `vou verificar agora mesmo`], [`it should work now`, `deve funcionar agora`], [`Can you try again?`, `pode tentar de novo?`], [`Anytime`, `sempre que precisar`]],
  focus: `“Keep + -ing” = algo que continua acontecendo: I keep getting an error. “Look into” = investigar, verificar.`,
  tasks: [`Simule um chamado de suporte: o usuário relata um erro e você resolve.`, `Descreva um problema que você resolveu recentemente, no passado.`] },

{ d: 63, title: `Asking a coworker for help`, pt: `Pedindo ajuda a um colega`, lvl: 'A2',
  en: [`Me: Hey, Priya, do you have a minute?`, `Priya: Sure, what's going on?`,
       `Me: I'm stuck on this report. The numbers don't match, and I can't figure out why.`, `Priya: Let me take a look. Hmm… did you include the returns?`,
       `Me: Oh no, I didn't. That makes sense!`, `Priya: It happens all the time. Just filter them out and run it again.`,
       `Me: Perfect, it matches now. Thanks, you saved my day.`, `Priya: No worries. If you need anything else, I'm right here.`],
  tr: [`Eu: Oi, Priya, você tem um minuto?`, `Priya: Claro, o que está acontecendo?`,
       `Eu: Estou travado neste relatório. Os números não batem, e não consigo entender por quê.`, `Priya: Deixa eu dar uma olhada. Hum… você incluiu as devoluções?`,
       `Eu: Ah não, não incluí. Faz sentido!`, `Priya: Acontece o tempo todo. É só filtrar elas e rodar de novo.`,
       `Eu: Perfeito, agora bate. Obrigado, você salvou o meu dia.`, `Priya: Imagina. Se precisar de mais alguma coisa, estou aqui.`],
  chunks: [[`do you have a minute?`, `tem um minuto?`], [`what's going on?`, `o que está acontecendo?`], [`I'm stuck on`, `estou travado em`], [`don't match`, `não batem`], [`I can't figure out why`, `não consigo entender por quê`], [`Let me take a look`, `deixa eu dar uma olhada`], [`That makes sense`, `faz sentido`], [`It happens all the time`, `acontece o tempo todo`], [`you saved my day`, `você salvou o meu dia`]],
  focus: `“Make sense” = fazer sentido. Nunca “have sense”. Pergunta: Does that make sense?`,
  tasks: [`Peça ajuda a um colega sobre algo em que você está travado.`, `Use “That makes sense” e “Does that make sense?” em duas frases.`] },

{ d: 64, title: `A quick update`, pt: `Uma atualização rápida`, lvl: 'A2',
  en: [`Every morning, my team has a fifteen-minute meeting. Each person shares what they did yesterday, what they're doing today, and if anything is blocking them.`,
       `Today it was my turn first. I said, “Yesterday I finished testing the new invoice layout. Today I'm going to fix two bugs that users reported.”`,
       `Then I said, “One thing is blocking me. I'm still waiting for access to the test system. Could someone help me with that?”`,
       `My manager said, “I'll follow up with the IT team after the meeting.” Short, clear, and done.`],
  tr: [`Toda manhã, minha equipe tem uma reunião de quinze minutos. Cada pessoa conta o que fez ontem, o que vai fazer hoje e se tem algo travando.`,
       `Hoje fui o primeiro. Eu disse: “Ontem terminei de testar o novo layout da fatura. Hoje vou corrigir dois bugs que os usuários relataram.”`,
       `Depois eu disse: “Uma coisa está me travando. Ainda estou esperando acesso ao sistema de testes. Alguém pode me ajudar com isso?”`,
       `Meu gerente disse: “Vou cobrar o time de TI depois da reunião.” Curto, claro, e pronto.`],
  chunks: [[`what they did yesterday`, `o que fizeram ontem`], [`is blocking them`, `está travando eles`], [`it was my turn`, `era a minha vez`], [`I finished testing`, `terminei de testar`], [`Today I'm going to`, `hoje vou`], [`I'm still waiting for`, `ainda estou esperando`], [`Could someone help me with that?`, `alguém pode me ajudar com isso?`], [`I'll follow up with`, `vou cobrar / acompanhar com`]],
  focus: `Atualização de reunião em 3 tempos: ontem (passado), hoje (going to) e bloqueio (still + -ing). Decore essa estrutura.`,
  tasks: [`Dê a sua atualização de hoje: ontem, hoje e um bloqueio.`, `Grave e cronometre: tem que caber em 45 segundos.`] },

{ d: 65, title: `Small talk with a client`, pt: `Papo rápido com um cliente`, lvl: 'A2',
  en: [`Client: Good morning, Lucas! How are things over there?`, `Me: Good morning, Emma! Things are good, thanks. Busy, but good. How's the weather in London?`,
       `Client: Gray and rainy, as usual. I'm jealous of your sunshine.`, `Me: Ha! You should come visit sometime. Did you have a good weekend?`,
       `Client: I did, thanks. I finally took my kids to the zoo. They loved it.`, `Me: That sounds like fun. Well, shall we get down to business?`,
       `Client: Yes, let's do it. I have a few questions about the new process.`],
  tr: [`Cliente: Bom dia, Lucas! Como estão as coisas por aí?`, `Eu: Bom dia, Emma! Tudo bem, obrigado. Corrido, mas bem. Como está o tempo em Londres?`,
       `Cliente: Cinza e chuvoso, como sempre. Estou com inveja do seu sol.`, `Eu: Ha! Você deveria vir visitar algum dia. Teve um bom fim de semana?`,
       `Cliente: Tive, obrigada. Finalmente levei meus filhos ao zoológico. Eles adoraram.`, `Eu: Parece divertido. Bom, vamos ao que interessa?`,
       `Cliente: Sim, vamos. Tenho algumas perguntas sobre o novo processo.`],
  chunks: [[`How are things over there?`, `como estão as coisas por aí?`], [`Busy, but good`, `corrido, mas bem`], [`as usual`, `como sempre`], [`I'm jealous of`, `estou com inveja de`], [`You should come visit sometime`, `você deveria vir visitar`], [`Did you have a good weekend?`, `teve um bom fim de semana?`], [`That sounds like fun`, `parece divertido`], [`shall we get down to business?`, `vamos ao que interessa?`]],
  focus: `Antes de reunião com estrangeiros, sempre tem 1 a 2 minutos de small talk. Tempo, fim de semana e “how are things” resolvem quase sempre.`,
  tasks: [`Faça 1 minuto de small talk antes de uma reunião imaginária e depois “get down to business”.`, `Pergunte sobre o fim de semana e reaja com “That sounds like fun / That sounds great”.`] },

{ d: 66, title: `Finally Friday`, pt: `Finalmente sexta`, lvl: 'A2',
  en: [`Mike: Finally, it's Friday! What a week.`, `Me: Tell me about it. I'm exhausted.`,
       `Mike: Are you doing anything fun this weekend?`, `Me: Not really. I just want to sleep in and catch up on my series. You?`,
       `Mike: A few of us are going out for drinks tonight. You should come!`, `Me: I'd love to, but I'm too tired. Maybe next time?`,
       `Mike: Sure, no pressure. Have a good weekend!`, `Me: You too. Don't work too hard on Monday!`],
  tr: [`Mike: Finalmente, é sexta! Que semana.`, `Eu: Nem me fala. Estou exausto.`,
       `Mike: Vai fazer algo legal neste fim de semana?`, `Eu: Não muito. Só quero dormir até tarde e colocar minhas séries em dia. E você?`,
       `Mike: Alguns de nós vão sair pra beber hoje à noite. Você devia ir!`, `Eu: Eu adoraria, mas estou cansado demais. Quem sabe da próxima?`,
       `Mike: Claro, sem pressão. Bom fim de semana!`, `Eu: Pra você também. Não trabalhe demais na segunda!`],
  chunks: [[`What a week`, `que semana`], [`Tell me about it`, `nem me fala`], [`I'm exhausted`, `estou exausto`], [`Are you doing anything fun`, `vai fazer algo legal?`], [`sleep in`, `dormir até tarde`], [`catch up on`, `colocar em dia`], [`I'd love to, but`, `eu adoraria, mas`], [`Maybe next time?`, `quem sabe da próxima?`], [`no pressure`, `sem pressão`]],
  focus: `Recusar com educação: “I'd love to, but…” + motivo + “Maybe next time?”. Nunca só “No”.`,
  tasks: [`Recuse 2 convites com educação e aceite 1 com “I'm down!”.`, `Conte o que você vai fazer neste fim de semana.`] },

{ d: 67, title: `A week at work`, pt: `Uma semana no trabalho`, lvl: 'A2', review: true,
  en: [`This week was intense. On Monday, a user called and said, “I keep getting an error message.” I looked into it right away and found the problem. A price condition had expired.`,
       `On Tuesday, I was stuck on a report, so I asked Priya, “Do you have a minute?” She took a look, and suddenly it all made sense.`,
       `In our morning meetings, I gave short updates: what I did yesterday, what I'm doing today, and what's blocking me.`,
       `On Friday, I had a call with a client from London. We talked about the weather first, and then we got down to business. What a week!`],
  tr: [`Esta semana foi intensa. Na segunda, uma usuária ligou e disse: “Fica dando mensagem de erro.” Verifiquei na hora e achei o problema. Uma condição de preço tinha vencido.`,
       `Na terça, eu estava travado num relatório, então perguntei para a Priya: “Tem um minuto?” Ela deu uma olhada e, de repente, tudo fez sentido.`,
       `Nas reuniões da manhã, dei atualizações curtas: o que fiz ontem, o que vou fazer hoje e o que está me travando.`,
       `Na sexta, tive uma call com uma cliente de Londres. Falamos do tempo primeiro e depois fomos ao que interessa. Que semana!`],
  chunks: [[`I keep getting an error message`, `fica dando erro`], [`I looked into it right away`, `verifiquei na hora`], [`I was stuck on`, `eu estava travado em`], [`Do you have a minute?`, `tem um minuto?`], [`it all made sense`, `tudo fez sentido`], [`what's blocking me`, `o que está me travando`], [`we got down to business`, `fomos ao que interessa`], [`What a week!`, `que semana!`]],
  focus: `Revisão: dias 61 a 66. Repare em “had expired” (tinha vencido): é o passado antes de outro passado.`,
  tasks: [`Grave 2 minutos contando a sua semana de trabalho ou estudo.`, `Explique o seu trabalho de novo, sem olhar o dia 61.`] },

{ d: 68, title: `While I was walking`, pt: `Enquanto eu estava andando`, lvl: 'A2',
  en: [`Last night, something strange happened. I was walking home from the gym, and I was listening to music.`,
       `While I was crossing the street, a dog started following me. It was small and white, and it looked lost.`,
       `I stopped and checked its collar. There was a phone number on it, so I called. A woman answered. She was crying, because she was looking for her dog everywhere.`,
       `Ten minutes later, she arrived and hugged the dog. She thanked me about twenty times. I got home late, but I was smiling the whole way.`],
  tr: [`Ontem à noite, aconteceu uma coisa estranha. Eu estava voltando a pé da academia e estava ouvindo música.`,
       `Enquanto eu atravessava a rua, um cachorro começou a me seguir. Era pequeno e branco, e parecia perdido.`,
       `Parei e olhei a coleira. Tinha um número de telefone, então liguei. Uma mulher atendeu. Ela estava chorando, porque estava procurando o cachorro por toda parte.`,
       `Dez minutos depois, ela chegou e abraçou o cachorro. Ela me agradeceu umas vinte vezes. Cheguei tarde em casa, mas fui sorrindo o caminho todo.`],
  chunks: [[`something strange happened`, `aconteceu uma coisa estranha`], [`I was walking home`, `eu estava voltando a pé`], [`While I was crossing the street`, `enquanto eu atravessava a rua`], [`started following me`, `começou a me seguir`], [`it looked lost`, `parecia perdido`], [`She was crying`, `ela estava chorando`], [`everywhere`, `por toda parte`], [`the whole way`, `o caminho todo`]],
  focus: `Passado contínuo (was / were + -ing) = o cenário que estava acontecendo. Passado simples = o fato que interrompe: While I was walking, a dog started following me.`,
  tasks: [`Conte algo que aconteceu enquanto você estava fazendo outra coisa.`, `Faça 3 frases: “I was …ing when …”.`] },

{ d: 69, title: `The best day of my life`, pt: `O melhor dia da minha vida`, lvl: 'A2',
  en: [`One of the best days of my life was my college graduation. I had worked and studied at the same time for five years, so it meant a lot to me.`,
       `My whole family came, even my grandmother, who doesn't like to travel. When they called my name, I heard my mom screaming in the audience. Everybody laughed.`,
       `After the ceremony, we went to a restaurant and celebrated until late. My dad gave a speech and almost cried.`,
       `That day, I realized that all the hard work was worth it.`],
  tr: [`Um dos melhores dias da minha vida foi a minha formatura da faculdade. Eu tinha trabalhado e estudado ao mesmo tempo por cinco anos, então significou muito para mim.`,
       `Minha família inteira veio, até a minha avó, que não gosta de viajar. Quando chamaram meu nome, ouvi minha mãe gritando na plateia. Todo mundo riu.`,
       `Depois da cerimônia, fomos a um restaurante e comemoramos até tarde. Meu pai fez um discurso e quase chorou.`,
       `Naquele dia, percebi que todo o esforço tinha valido a pena.`],
  chunks: [[`One of the best days of my life`, `um dos melhores dias da minha vida`], [`at the same time`, `ao mesmo tempo`], [`it meant a lot to me`, `significou muito pra mim`], [`My whole family came`, `minha família inteira veio`], [`When they called my name`, `quando chamaram meu nome`], [`celebrated until late`, `comemoramos até tarde`], [`gave a speech`, `fez um discurso`], [`all the hard work was worth it`, `todo o esforço valeu a pena`]],
  focus: `“Mean a lot” = significar muito. “Mean” no passado é “meant”. “Hard work” = esforço, trabalho duro.`,
  tasks: [`Conte um dos melhores dias da sua vida: quando, quem estava, o que aconteceu.`, `Diga algo que “meant a lot to you”.`] },

{ d: 70, title: `A scary moment`, pt: `Um momento de susto`, lvl: 'A2',
  en: [`A few years ago, I was home alone on a stormy night. Suddenly, the power went out, and the whole apartment went dark.`,
       `I was looking for a flashlight when I heard a noise in the kitchen. My heart was beating so fast. I grabbed my phone and slowly walked toward the sound.`,
       `I turned on the phone light and saw… my cat. She had knocked a pan off the counter.`,
       `I laughed out loud, but honestly, I was scared to death for a minute. Now, every time there's a storm, I make sure I know where the flashlight is.`],
  tr: [`Alguns anos atrás, eu estava sozinho em casa numa noite de tempestade. De repente, a luz acabou, e o apartamento inteiro ficou escuro.`,
       `Eu estava procurando uma lanterna quando ouvi um barulho na cozinha. Meu coração estava batendo muito rápido. Peguei o celular e fui devagar em direção ao som.`,
       `Liguei a luz do celular e vi… a minha gata. Ela tinha derrubado uma panela do balcão.`,
       `Eu ri alto, mas, sinceramente, fiquei morrendo de medo por um minuto. Agora, toda vez que tem tempestade, eu garanto que sei onde está a lanterna.`],
  chunks: [[`home alone`, `sozinho em casa`], [`the power went out`, `a luz acabou`], [`went dark`, `ficou escuro`], [`I was looking for`, `eu estava procurando`], [`My heart was beating so fast`, `meu coração batia muito rápido`], [`I grabbed`, `peguei (rápido)`], [`I laughed out loud`, `eu ri alto`], [`I was scared to death`, `fiquei morrendo de medo`], [`every time`, `toda vez que`]],
  focus: `Para contar histórias, nativos usam “Suddenly…”, “I was …ing when…” e terminam com uma lição ou piada.`,
  tasks: [`Conte um momento em que você levou um susto, com começo, susto e final.`, `Use “Suddenly” e “I was …ing when” na sua história.`] },

{ d: 71, title: `When I was a kid`, pt: `Quando eu era criança`, lvl: 'A2',
  en: [`When I was a kid, I lived in a small town in the countryside. Life was simple. We didn't have internet at home, so I used to play outside all day.`,
       `My friends and I used to ride our bikes everywhere and play soccer in the street until it got dark.`,
       `I used to be really afraid of dogs, but now I love them. And I didn't use to like vegetables. My mom had to hide them in my food.`,
       `I miss those days sometimes. Everything felt bigger, and I never worried about anything.`],
  tr: [`Quando eu era criança, morava numa cidadezinha no interior. A vida era simples. Não tínhamos internet em casa, então eu costumava brincar na rua o dia todo.`,
       `Meus amigos e eu andávamos de bicicleta por todo lado e jogávamos futebol na rua até escurecer.`,
       `Eu tinha muito medo de cachorro, mas hoje eu amo. E eu não gostava de verdura. Minha mãe tinha que esconder na minha comida.`,
       `Às vezes sinto falta daquela época. Tudo parecia maior, e eu nunca me preocupava com nada.`],
  chunks: [[`When I was a kid`, `quando eu era criança`], [`in the countryside`, `no interior`], [`I used to play outside`, `eu brincava na rua`], [`ride our bikes`, `andar de bicicleta`], [`until it got dark`, `até escurecer`], [`I used to be really afraid of`, `eu tinha muito medo de`], [`I didn't use to like`, `eu não gostava de`], [`I miss those days`, `sinto falta daquela época`], [`I never worried about anything`, `nunca me preocupava com nada`]],
  focus: `“Used to” = costumava (hábito do passado que acabou). Negativa: didn't use to (sem o “d”).`,
  tasks: [`Fale 5 coisas que você costumava fazer quando criança.`, `Diga 1 coisa que você não gostava e agora gosta: “I didn't use to like…, but now…”.`] },

{ d: 72, title: `A movie you should watch`, pt: `Um filme que você deveria ver`, lvl: 'A2',
  en: [`Last weekend, I watched a movie called “The Intern,” and I really recommend it. It's a comedy, but it's also kind of emotional.`,
       `It's about a seventy-year-old man who starts working as an intern at a young fashion company. At first, nobody takes him seriously. But little by little, he becomes everyone's friend and helps them with their problems.`,
       `What I liked the most was the dialogue. It's simple, clear English, so it's great for learners. I watched it with English subtitles and understood most of it.`,
       `If you're looking for something light and positive, you should definitely watch it.`],
  tr: [`No fim de semana passado, assisti um filme chamado “Um Senhor Estagiário”, e recomendo muito. É uma comédia, mas também é meio emocionante.`,
       `É sobre um homem de setenta anos que começa a trabalhar como estagiário numa empresa jovem de moda. No começo, ninguém leva ele a sério. Mas, pouco a pouco, ele vira amigo de todo mundo e ajuda todos com seus problemas.`,
       `O que eu mais gostei foram os diálogos. É um inglês simples e claro, então é ótimo para quem está aprendendo. Assisti com legenda em inglês e entendi a maior parte.`,
       `Se você está procurando algo leve e positivo, deveria assistir com certeza.`],
  chunks: [[`I really recommend it`, `recomendo muito`], [`kind of emotional`, `meio emocionante`], [`It's about`, `é sobre`], [`nobody takes him seriously`, `ninguém leva ele a sério`], [`What I liked the most was`, `o que eu mais gostei foi`], [`understood most of it`, `entendi a maior parte`], [`If you're looking for something`, `se você procura algo`], [`you should definitely watch it`, `você deveria assistir com certeza`]],
  focus: `Para falar de filme e série: “It's about…” (enredo), “What I liked the most was…” (opinião), “You should watch it” (recomendação).`,
  tasks: [`Recomende um filme ou série em 4 frases: nome, sobre o quê, o que gostou, para quem.`, `Assista o trailer desse filme no YouTube com legenda em inglês.`] },

{ d: 73, title: `Have you ever…?`, pt: `Você já…?`, lvl: 'A2',
  en: [`Leo: Have you ever been to another country?`, `Me: Yes, I've been to the United States once. What about you?`,
       `Leo: I've never left Brazil, but I've traveled a lot inside the country. Have you ever eaten something really strange?`,
       `Me: Hmm… I've tried alligator. It tastes kind of like chicken.`, `Leo: No way! I've never tried that.`,
       `Me: Have you ever met someone famous?`, `Leo: Actually, yes! I saw a famous singer at the airport last year. I was too nervous to talk to him.`,
       `Me: That's so cool. I've never seen anyone famous in real life.`],
  tr: [`Leo: Você já foi para outro país?`, `Eu: Sim, já fui para os Estados Unidos uma vez. E você?`,
       `Leo: Nunca saí do Brasil, mas já viajei muito dentro do país. Você já comeu algo muito estranho?`,
       `Eu: Hum… já provei jacaré. Tem um gosto meio de frango.`, `Leo: Não acredito! Nunca provei isso.`,
       `Eu: Você já conheceu alguém famoso?`, `Leo: Na verdade, sim! Vi um cantor famoso no aeroporto no ano passado. Fiquei nervoso demais para falar com ele.`,
       `Eu: Que demais. Eu nunca vi ninguém famoso pessoalmente.`],
  chunks: [[`Have you ever been to`, `você já foi para…?`], [`I've been to`, `já fui para`], [`I've never left`, `nunca saí de`], [`Have you ever eaten`, `você já comeu…?`], [`I've tried`, `já provei`], [`It tastes kind of like`, `tem gosto meio de`], [`No way!`, `não acredito!`], [`too nervous to`, `nervoso demais para`], [`in real life`, `pessoalmente / na vida real`]],
  focus: `“Have you ever…?” pergunta experiências da vida, sem dizer quando. Se disser quando (last year), muda para o passado simples: I saw him last year.`,
  tasks: [`Responda 5 perguntas “Have you ever…?” sobre você.`, `Faça 3 perguntas “Have you ever…?” para alguém.`] },

{ d: 74, title: `Stories from my life`, pt: `Histórias da minha vida`, lvl: 'A2', review: true,
  en: [`When I was a kid, I used to play outside until it got dark. I used to be afraid of dogs, but now I love them. Last week, I was walking home when a lost dog started following me. I helped it find its owner.`,
       `One of the best days of my life was my graduation. It meant a lot to me, and all the hard work was worth it.`,
       `I've been to the United States once, and I've tried some strange food. But I've never met anyone famous.`,
       `Last weekend, I watched a great movie. It's about an older man who works as an intern. I really recommend it.`],
  tr: [`Quando eu era criança, eu brincava na rua até escurecer. Eu tinha medo de cachorro, mas hoje eu amo. Semana passada, eu estava voltando para casa quando um cachorro perdido começou a me seguir. Ajudei ele a achar a dona.`,
       `Um dos melhores dias da minha vida foi a minha formatura. Significou muito para mim, e todo o esforço valeu a pena.`,
       `Já fui para os Estados Unidos uma vez e já provei umas comidas estranhas. Mas nunca conheci ninguém famoso.`,
       `No fim de semana passado, assisti um filme ótimo. É sobre um senhor que trabalha como estagiário. Recomendo muito.`],
  chunks: [[`I used to play outside`, `eu brincava na rua`], [`I was walking home when`, `eu estava voltando quando`], [`It meant a lot to me`, `significou muito pra mim`], [`was worth it`, `valeu a pena`], [`I've been to`, `já fui para`], [`I've never met`, `nunca conheci`], [`It's about`, `é sobre`], [`I really recommend it`, `recomendo muito`]],
  focus: `Revisão: dias 68 a 73. Quatro passados num texto só: used to, was …ing, passado simples e present perfect.`,
  tasks: [`Grave 2 minutos contando 2 histórias da sua vida.`, `Ouça e marque: você usou pelo menos um “used to” e um “I've…”?`] },

{ d: 75, title: `My goals for next year`, pt: `Minhas metas para o ano que vem`, lvl: 'A2',
  en: [`Every December, I write down my goals for the next year. This year, I'm going to be more specific, because last year my goals were too vague.`,
       `First, I'm going to reach a B1 level in English. To do that, I'll study one hour a day and have at least one conversation a week.`,
       `Second, I want to get a certification in my area. I've already started the online course.`,
       `Third, I'd like to save money for a trip abroad. I'm planning to put aside ten percent of my salary every month. I know it won't be easy, but I'm ready.`],
  tr: [`Todo dezembro, escrevo minhas metas para o ano seguinte. Este ano, vou ser mais específico, porque no ano passado minhas metas foram vagas demais.`,
       `Primeiro, vou chegar ao nível B1 em inglês. Para isso, vou estudar uma hora por dia e ter pelo menos uma conversa por semana.`,
       `Segundo, quero tirar uma certificação na minha área. Já comecei o curso online.`,
       `Terceiro, gostaria de juntar dinheiro para uma viagem internacional. Estou planejando guardar dez por cento do meu salário todo mês. Sei que não vai ser fácil, mas estou pronto.`],
  chunks: [[`I write down`, `eu anoto`], [`too vague`, `vagas demais`], [`I'm going to reach`, `vou chegar a`], [`To do that`, `para isso`], [`at least one conversation a week`, `pelo menos uma conversa por semana`], [`I've already started`, `já comecei`], [`save money for`, `juntar dinheiro para`], [`put aside`, `guardar / separar`], [`it won't be easy`, `não vai ser fácil`]],
  focus: `Organize ideias com “First… Second… Third…” e explique o como com “To do that, I'll…”. Funciona em reunião, entrevista e apresentação.`,
  tasks: [`Diga 3 metas para o próximo ano com “First, Second, Third” e como vai alcançá-las.`, `Escreva as metas num papel, em inglês, e guarde.`] },

{ d: 76, title: `If I won the lottery`, pt: `Se eu ganhasse na loteria`, lvl: 'A2',
  en: [`Ana: What would you do if you won the lottery?`, `Me: First, I would buy a house for my parents. They've worked so hard their whole lives.`,
       `Ana: That's sweet. Would you quit your job?`, `Me: Probably not right away. I like what I do. But I would travel a lot more.`,
       `Ana: Where would you go first?`, `Me: Japan, for sure. I've always wanted to go. What about you?`,
       `Ana: If I had that much money, I would open a small café by the beach.`, `Me: That sounds like a dream. If you open it, I'll be your first customer!`],
  tr: [`Ana: O que você faria se ganhasse na loteria?`, `Eu: Primeiro, compraria uma casa para os meus pais. Eles trabalharam muito a vida inteira.`,
       `Ana: Que fofo. Você largaria o emprego?`, `Eu: Provavelmente não de cara. Gosto do que faço. Mas viajaria muito mais.`,
       `Ana: Para onde você iria primeiro?`, `Eu: Japão, com certeza. Sempre quis ir. E você?`,
       `Ana: Se eu tivesse tanto dinheiro, abriria um cafezinho na praia.`, `Eu: Parece um sonho. Se você abrir, vou ser seu primeiro cliente!`],
  chunks: [[`What would you do if`, `o que você faria se…?`], [`I would buy`, `eu compraria`], [`their whole lives`, `a vida inteira`], [`Would you quit your job?`, `você largaria o emprego?`], [`right away`, `de cara / imediatamente`], [`for sure`, `com certeza`], [`If I had that much money`, `se eu tivesse tanto dinheiro`], [`That sounds like a dream`, `parece um sonho`]],
  focus: `Imaginação: If + passado, would + verbo: If I won, I would travel. Real e possível: If + presente, will: If you open it, I'll be your first customer.`,
  tasks: [`Responda: “What would you do if you won the lottery?” com 4 coisas.`, `Faça 2 frases com “If I had more time, I would…”.`] },

{ d: 77, title: `A big decision`, pt: `Uma grande decisão`, lvl: 'A2',
  en: [`I'm thinking about changing jobs. I got an offer from another company last week, and I don't know what to do.`,
       `On the one hand, the new job pays more, and I would work with international teams. That's great for my English and my career.`,
       `On the other hand, I really like my current team, and the new office is far from my place. I would spend almost two hours a day in traffic.`,
       `I made a list of pros and cons. I'm also going to talk to my old boss, because she always gives good advice. I need to decide by Friday.`],
  tr: [`Estou pensando em mudar de emprego. Recebi uma proposta de outra empresa semana passada e não sei o que fazer.`,
       `Por um lado, o emprego novo paga mais, e eu trabalharia com equipes internacionais. Isso é ótimo para o meu inglês e a minha carreira.`,
       `Por outro lado, gosto muito da minha equipe atual, e o escritório novo é longe de casa. Eu passaria quase duas horas por dia no trânsito.`,
       `Fiz uma lista de prós e contras. Também vou conversar com a minha antiga chefe, porque ela sempre dá bons conselhos. Preciso decidir até sexta.`],
  chunks: [[`I'm thinking about`, `estou pensando em`], [`I got an offer`, `recebi uma proposta`], [`I don't know what to do`, `não sei o que fazer`], [`On the one hand`, `por um lado`], [`On the other hand`, `por outro lado`], [`my current team`, `minha equipe atual`], [`pros and cons`, `prós e contras`], [`gives good advice`, `dá bons conselhos`], [`I need to decide by`, `preciso decidir até`]],
  focus: `Falso cognato: “current” = atual. “Actually” = na verdade. “Advice” não tem plural: some advice, a piece of advice.`,
  tasks: [`Fale de uma decisão que você precisa tomar, com “On the one hand… On the other hand…”.`, `Faça uma lista de prós e contras em inglês, em voz alta.`] },

{ d: 78, title: `If I were you`, pt: `Se eu fosse você`, lvl: 'A2',
  en: [`Friend: I don't know what to do. I want to learn English faster, but I never have time.`, `Me: If I were you, I'd start small. Even fifteen minutes a day makes a difference.`,
       `Friend: But I'm always so tired after work.`, `Me: Then why don't you study in the morning, before work? Or on the bus?`,
       `Friend: Hmm, I could listen to podcasts on the bus.`, `Me: Exactly. And you should stop studying only grammar. Try to listen and speak every day.`,
       `Friend: That's good advice. Thanks.`, `Me: Anytime. And don't give up. It takes time, but it works.`],
  tr: [`Amigo: Não sei o que fazer. Quero aprender inglês mais rápido, mas nunca tenho tempo.`, `Eu: Se eu fosse você, começaria pequeno. Até quinze minutos por dia fazem diferença.`,
       `Amigo: Mas estou sempre muito cansado depois do trabalho.`, `Eu: Então por que você não estuda de manhã, antes do trabalho? Ou no ônibus?`,
       `Amigo: Hum, eu poderia ouvir podcasts no ônibus.`, `Eu: Exatamente. E você deveria parar de estudar só gramática. Tente ouvir e falar todo dia.`,
       `Amigo: Bom conselho. Valeu.`, `Eu: Sempre que precisar. E não desista. Leva tempo, mas funciona.`],
  chunks: [[`If I were you, I'd`, `se eu fosse você, eu…`], [`start small`, `começar pequeno`], [`makes a difference`, `faz diferença`], [`why don't you`, `por que você não…?`], [`I could`, `eu poderia`], [`Exactly`, `exatamente`], [`you should stop`, `você deveria parar de`], [`That's good advice`, `bom conselho`], [`don't give up`, `não desista`]],
  focus: `Conselhos do mais leve ao mais forte: “You could…” (sugestão), “Why don't you…?” (ideia), “You should…” (conselho), “If I were you, I'd…” (opinião pessoal).`,
  tasks: [`Dê 4 conselhos para um amigo que quer economizar dinheiro, usando as 4 formas.`, `Peça um conselho sobre algo real da sua vida.`] },

{ d: 79, title: `Planning a trip together`, pt: `Planejando uma viagem juntos`, lvl: 'A2',
  en: [`Bruno: So, where should we go in July?`, `Me: We could go to Chile. Flights are pretty cheap right now.`,
       `Bruno: Chile sounds great. But it's winter there in July. Is it going to be too cold?`, `Me: A little, but that's the best time to see snow. Have you ever seen snow?`,
       `Bruno: Never! Okay, I'm in. How long should we stay?`, `Me: How about a week? We could spend four days in Santiago and three in the mountains.`,
       `Bruno: Perfect. Let's book the flights this weekend, before the prices go up.`, `Me: Deal. I'll look for a place to stay.`],
  tr: [`Bruno: E aí, para onde a gente deveria ir em julho?`, `Eu: A gente podia ir para o Chile. As passagens estão bem baratas agora.`,
       `Bruno: Chile parece ótimo. Mas lá é inverno em julho. Vai fazer frio demais?`, `Eu: Um pouco, mas é a melhor época pra ver neve. Você já viu neve?`,
       `Bruno: Nunca! Beleza, tô dentro. Quanto tempo a gente fica?`, `Eu: Que tal uma semana? Podíamos passar quatro dias em Santiago e três nas montanhas.`,
       `Bruno: Perfeito. Vamos comprar as passagens neste fim de semana, antes que os preços subam.`, `Eu: Fechado. Eu procuro um lugar para ficar.`],
  chunks: [[`where should we go`, `pra onde a gente deveria ir?`], [`We could go to`, `a gente podia ir para`], [`pretty cheap right now`, `bem barato agora`], [`Is it going to be too cold?`, `vai fazer frio demais?`], [`the best time to`, `a melhor época para`], [`I'm in`, `tô dentro`], [`How long should we stay?`, `quanto tempo a gente fica?`], [`before the prices go up`, `antes que os preços subam`], [`Deal`, `fechado`]],
  focus: `Planejar junto: “Should we…?” (pergunta), “We could…” (sugestão), “Let's…” (decisão), “Deal” (fechado).`,
  tasks: [`Planeje uma viagem com um amigo imaginário: destino, época, duração, hospedagem.`, `Use “Should we…?”, “We could…” e “Let's…” pelo menos uma vez.`] },

{ d: 80, title: `The future of work`, pt: `O futuro do trabalho`, lvl: 'A2',
  en: [`Everybody is talking about artificial intelligence. Some people think it will take their jobs. Others think it will make work easier.`,
       `In my opinion, AI won't replace most people, but it will change the way we work. People who know how to use it will have an advantage.`,
       `In my area, I think systems will become more automatic. We'll spend less time on boring tasks and more time solving real problems.`,
       `One thing I'm sure about: English will be even more important. Most tools and documentation are in English, so I'm studying now to be ready.`],
  tr: [`Todo mundo está falando de inteligência artificial. Algumas pessoas acham que ela vai tomar seus empregos. Outras acham que vai facilitar o trabalho.`,
       `Na minha opinião, a IA não vai substituir a maioria das pessoas, mas vai mudar o jeito como trabalhamos. Quem souber usar vai ter vantagem.`,
       `Na minha área, acho que os sistemas vão ficar mais automáticos. Vamos passar menos tempo em tarefas chatas e mais tempo resolvendo problemas reais.`,
       `Uma coisa eu tenho certeza: o inglês vai ser ainda mais importante. A maioria das ferramentas e documentações está em inglês, então estou estudando agora para estar pronto.`],
  chunks: [[`Everybody is talking about`, `todo mundo está falando de`], [`it will take their jobs`, `vai tomar os empregos deles`], [`make work easier`, `facilitar o trabalho`], [`won't replace`, `não vai substituir`], [`the way we work`, `o jeito como trabalhamos`], [`will have an advantage`, `vai ter vantagem`], [`One thing I'm sure about`, `uma coisa eu tenho certeza`], [`even more important`, `ainda mais importante`]],
  focus: `“Will” para previsões e opiniões sobre o futuro. Negativa: won't (will not). “Even more” = ainda mais.`,
  tasks: [`Dê 3 previsões sobre o futuro da sua área com “I think… will…”.`, `Diga 1 coisa que não vai mudar: “… won't change”.`] },

{ d: 81, title: `Looking ahead`, pt: `Olhando para a frente`, lvl: 'A2', review: true,
  en: [`I'm thinking about my future a lot these days. I got a job offer, and on the one hand it's a great opportunity. On the other hand, I'd miss my team.`,
       `A friend told me, “If I were you, I'd take it. You'll learn a lot.” I think she's right.`,
       `For next year, I have three goals. First, I'm going to reach B1 in English. Second, I'll get a certification. Third, I'm saving money for a trip to Chile with Bruno.`,
       `If I won the lottery, I would travel the world. But since that probably won't happen, I'll keep working and studying. One thing I'm sure about: English will open doors for me.`],
  tr: [`Tenho pensado muito no meu futuro ultimamente. Recebi uma proposta de emprego e, por um lado, é uma ótima oportunidade. Por outro lado, eu sentiria falta da minha equipe.`,
       `Uma amiga me disse: “Se eu fosse você, aceitaria. Você vai aprender muito.” Acho que ela tem razão.`,
       `Para o ano que vem, tenho três metas. Primeiro, vou chegar ao B1 em inglês. Segundo, vou tirar uma certificação. Terceiro, estou juntando dinheiro para uma viagem ao Chile com o Bruno.`,
       `Se eu ganhasse na loteria, viajaria o mundo. Mas como isso provavelmente não vai acontecer, vou continuar trabalhando e estudando. Uma coisa eu tenho certeza: o inglês vai abrir portas para mim.`],
  chunks: [[`I'm thinking about`, `estou pensando em`], [`On the other hand`, `por outro lado`], [`If I were you, I'd`, `se eu fosse você, eu…`], [`I'm going to reach`, `vou chegar a`], [`I'm saving money for`, `estou juntando dinheiro para`], [`If I won the lottery`, `se eu ganhasse na loteria`], [`probably won't happen`, `provavelmente não vai acontecer`], [`will open doors for me`, `vai abrir portas pra mim`]],
  focus: `Revisão: dias 75 a 80. Todo o futuro num texto: going to (plano), will (previsão), presente contínuo (já em andamento) e would (imaginação).`,
  tasks: [`Grave 2 minutos sobre o seu futuro: metas, decisões e sonhos.`, `Use pelo menos um “would” e um “going to”.`] },

{ d: 82, title: `Agreeing and disagreeing`, pt: `Concordando e discordando`, lvl: 'A2',
  en: [`Carla: I think everyone should work from the office five days a week.`, `Me: Hmm, I'm not sure about that. A lot of people work better from home.`,
       `Carla: Maybe, but teams communicate better in person.`, `Me: That's a good point. I agree that meetings are easier in person.`,
       `Carla: So you agree with me?`, `Me: Partly. I see your point, but I don't think five days is necessary. Two or three days would be enough.`,
       `Carla: I guess that's fair.`, `Me: Let's agree to disagree on the rest!`],
  tr: [`Carla: Acho que todo mundo deveria trabalhar no escritório cinco dias por semana.`, `Eu: Hum, não tenho certeza disso. Muita gente trabalha melhor de casa.`,
       `Carla: Talvez, mas as equipes se comunicam melhor pessoalmente.`, `Eu: Bom argumento. Concordo que reuniões são mais fáceis pessoalmente.`,
       `Carla: Então você concorda comigo?`, `Eu: Em parte. Entendo o seu ponto, mas não acho que cinco dias seja necessário. Dois ou três dias seriam suficientes.`,
       `Carla: Acho que é justo.`, `Eu: Vamos concordar em discordar no resto!`],
  chunks: [[`I'm not sure about that`, `não tenho certeza disso`], [`That's a good point`, `bom argumento`], [`I agree that`, `concordo que`], [`Partly`, `em parte`], [`I see your point, but`, `entendo o seu ponto, mas`], [`I don't think`, `não acho que`], [`would be enough`, `seria suficiente`], [`that's fair`, `é justo`], [`agree to disagree`, `concordar em discordar`]],
  focus: `Discordar com educação: comece reconhecendo (“That's a good point” / “I see your point”) e depois use “but”. Em inglês, a negação vai no “think”: I don't think it's necessary.`,
  tasks: [`Escolha um tema polêmico leve (abacaxi na pizza, home office) e defenda os dois lados.`, `Discorde de 3 frases com educação.`] },

{ d: 83, title: `I need your advice`, pt: `Preciso do seu conselho`, lvl: 'A2',
  en: [`Me: Can I ask you something? I need your advice.`, `Sara: Of course. What's wrong?`,
       `Me: I have a presentation in English next week, and I'm really nervous. I'm afraid I'll freeze in front of everyone.`, `Sara: That's normal. Have you practiced it out loud?`,
       `Me: Not yet. I just read it in my head.`, `Sara: That's the problem. Practice out loud at least five times. Record yourself, too.`,
       `Me: What if I forget a word?`, `Sara: Just say it in a different way. Nobody will notice. And remember, they want you to do well.`,
       `Me: That makes me feel better. Thanks, Sara.`],
  tr: [`Eu: Posso te perguntar uma coisa? Preciso do seu conselho.`, `Sara: Claro. O que houve?`,
       `Eu: Tenho uma apresentação em inglês semana que vem e estou muito nervoso. Tenho medo de travar na frente de todo mundo.`, `Sara: Isso é normal. Você já ensaiou em voz alta?`,
       `Eu: Ainda não. Só li na cabeça.`, `Sara: Esse é o problema. Ensaie em voz alta pelo menos cinco vezes. Grave você também.`,
       `Eu: E se eu esquecer uma palavra?`, `Sara: É só dizer de outro jeito. Ninguém vai perceber. E lembre: eles querem que você se saia bem.`,
       `Eu: Isso me deixa mais tranquilo. Obrigado, Sara.`],
  chunks: [[`Can I ask you something?`, `posso te perguntar uma coisa?`], [`I need your advice`, `preciso do seu conselho`], [`What's wrong?`, `o que houve?`], [`I'm afraid I'll freeze`, `tenho medo de travar`], [`in front of everyone`, `na frente de todo mundo`], [`out loud`, `em voz alta`], [`What if`, `e se…?`], [`in a different way`, `de outro jeito`], [`Nobody will notice`, `ninguém vai perceber`], [`That makes me feel better`, `isso me deixa melhor`]],
  focus: `“What if…?” = e se…? É ótimo para falar de preocupações: What if it rains? What if I forget?`,
  tasks: [`Conte uma preocupação real e peça conselho.`, `Faça 3 perguntas “What if…?” sobre uma situação que te deixa nervoso.`] },

{ d: 84, title: `Did you hear the news?`, pt: `Você viu a notícia?`, lvl: 'A2',
  en: [`Tom: Did you hear the news? They're building a new subway line near our office.`, `Me: Really? I had no idea. When is it going to be ready?`,
       `Tom: According to the article, in about three years.`, `Me: Three years? That's a long time. But it'll be great when it's done.`,
       `Tom: Yeah. I read that it will cut the commute in half for a lot of people.`, `Me: Wow, that's huge. I spend almost an hour on the bus every day.`,
       `Tom: Same here. Apparently, the construction starts next month, so traffic is going to get worse first.`, `Me: Great… Thanks for the bad news!`],
  tr: [`Tom: Você viu a notícia? Vão construir uma nova linha de metrô perto do nosso escritório.`, `Eu: Sério? Eu não fazia ideia. Quando vai ficar pronta?`,
       `Tom: Segundo a matéria, em uns três anos.`, `Eu: Três anos? É muito tempo. Mas vai ser ótimo quando ficar pronto.`,
       `Tom: É. Li que vai cortar o tempo de deslocamento pela metade para muita gente.`, `Eu: Nossa, isso é enorme. Passo quase uma hora no ônibus todo dia.`,
       `Tom: Eu também. Pelo jeito, a obra começa mês que vem, então o trânsito vai piorar primeiro.`, `Eu: Ótimo… Obrigado pela notícia ruim!`],
  chunks: [[`Did you hear the news?`, `viu a notícia?`], [`I had no idea`, `eu não fazia ideia`], [`According to`, `segundo / de acordo com`], [`That's a long time`, `é muito tempo`], [`I read that`, `li que`], [`cut the commute in half`, `cortar o deslocamento pela metade`], [`that's huge`, `isso é enorme`], [`Apparently`, `pelo jeito / aparentemente`], [`is going to get worse`, `vai piorar`]],
  focus: `Para contar notícia: “Did you hear…?”, “I read that…”, “According to…”, “Apparently…”. “News” é singular: The news is good.`,
  tasks: [`Leia uma notícia no News in Levels (nível 1 ou 2) e conte para alguém com essas expressões.`, `Reaja a 3 notícias: “Really?”, “That's huge”, “I had no idea”.`] },

{ d: 85, title: `How I feel`, pt: `Como eu me sinto`, lvl: 'A2',
  en: [`It's not always easy to talk about feelings in another language, but it's important. Here's how I've been feeling lately.`,
       `I'm excited about my new project, but I'm also a little worried about the deadline. When I think about the presentation, I get anxious.`,
       `On the weekend, I felt relieved when everything was finally done. I was proud of myself, and I didn't feel stressed for the first time in weeks.`,
       `My English is getting better, and that makes me happy. Sometimes I still feel frustrated when I can't find the right word. But I'm more confident than I used to be.`],
  tr: [`Nem sempre é fácil falar de sentimentos em outra língua, mas é importante. Veja como tenho me sentido ultimamente.`,
       `Estou animado com o meu projeto novo, mas também um pouco preocupado com o prazo. Quando penso na apresentação, fico ansioso.`,
       `No fim de semana, me senti aliviado quando tudo finalmente ficou pronto. Fiquei orgulhoso de mim e, pela primeira vez em semanas, não me senti estressado.`,
       `Meu inglês está melhorando, e isso me deixa feliz. Às vezes ainda fico frustrado quando não acho a palavra certa. Mas estou mais confiante do que antes.`],
  chunks: [[`how I've been feeling lately`, `como tenho me sentido ultimamente`], [`I'm excited about`, `estou animado com`], [`worried about`, `preocupado com`], [`I get anxious`, `fico ansioso`], [`I felt relieved`, `me senti aliviado`], [`I was proud of myself`, `fiquei orgulhoso de mim`], [`for the first time in weeks`, `pela primeira vez em semanas`], [`that makes me happy`, `isso me deixa feliz`], [`more confident than I used to be`, `mais confiante do que antes`]],
  focus: `Sentimento + preposição: excited about, worried about, proud of, afraid of, tired of. Lembre: excited = animado.`,
  tasks: [`Diga como você está se sentindo esta semana, com 4 sentimentos diferentes.`, `Complete: “I get anxious when…”, “I feel proud when…”.`] },

{ d: 86, title: `Mistakes Brazilians make`, pt: `Erros que brasileiros cometem`, lvl: 'A2',
  en: [`Some mistakes are very common for Brazilians, because we translate directly from Portuguese. Here are the classics.`,
       `We say “I am agree,” but the right way is simply “I agree.” We say “People is nice,” but “people” is plural, so it's “People are nice.”`,
       `We say “Explain me,” but in English you explain something to someone: “Can you explain it to me?” We say “I have twenty years,” but it's “I'm twenty.”`,
       `We also say “I'm living here since 2020,” but the correct form is “I've been living here since 2020.” Fix these five, and you'll sound much more natural.`],
  tr: [`Alguns erros são muito comuns para brasileiros, porque traduzimos direto do português. Aqui estão os clássicos.`,
       `Dizemos “I am agree”, mas o certo é simplesmente “I agree”. Dizemos “People is nice”, mas “people” é plural, então é “People are nice”.`,
       `Dizemos “Explain me”, mas em inglês você explica algo para alguém: “Can you explain it to me?” Dizemos “I have twenty years”, mas é “I'm twenty”.`,
       `Também dizemos “I'm living here since 2020”, mas a forma certa é “I've been living here since 2020”. Corrija esses cinco e você vai soar muito mais natural.`],
  chunks: [[`translate directly from`, `traduzir direto do`], [`the right way is`, `o certo é`], [`I agree`, `concordo`], [`People are nice`, `as pessoas são legais`], [`Can you explain it to me?`, `pode me explicar?`], [`I'm twenty`, `tenho vinte anos`], [`I've been living here since`, `moro aqui desde`], [`you'll sound much more natural`, `vai soar muito mais natural`]],
  focus: `Grave você falando 1 minuto e procure esses 5 erros. Achar o próprio erro é o jeito mais rápido de parar de cometê-lo.`,
  tasks: [`Faça uma frase certa para cada um dos 5 erros.`, `Diga há quanto tempo você mora onde mora: “I've been living here since…”.`] },

{ d: 87, title: `Keeping the conversation going`, pt: `Mantendo a conversa`, lvl: 'A2',
  en: [`The secret of good conversation is simple: ask follow-up questions and react to what people say.`,
       `If someone says, “I went to Portugal last month,” don't just say, “Nice.” Ask, “Oh, really? How was it?” or “What did you like the most?”`,
       `Show interest with small reactions: “No way!”, “That's crazy!”, “Seriously?”, “I know, right?” And when you don't understand, ask, “What do you mean?”`,
       `When you want to change the subject, say, “By the way…” or “Speaking of…”. People will think you're a great talker, even if your English isn't perfect.`],
  tr: [`O segredo de uma boa conversa é simples: faça perguntas de continuação e reaja ao que as pessoas dizem.`,
       `Se alguém diz “Fui para Portugal mês passado”, não diga só “Legal”. Pergunte: “Ah, é? Como foi?” ou “Do que você mais gostou?”`,
       `Mostre interesse com reações curtas: “Não acredito!”, “Que loucura!”, “Sério?”, “Pois é, né?” E quando não entender, pergunte: “Como assim?”`,
       `Quando quiser mudar de assunto, diga “Aliás…” ou “Falando em…”. As pessoas vão achar que você é ótimo de papo, mesmo que o seu inglês não seja perfeito.`],
  chunks: [[`ask follow-up questions`, `fazer perguntas de continuação`], [`Oh, really? How was it?`, `ah, é? como foi?`], [`What did you like the most?`, `do que você mais gostou?`], [`That's crazy!`, `que loucura!`], [`Seriously?`, `sério?`], [`I know, right?`, `pois é, né?`], [`What do you mean?`, `como assim?`], [`By the way`, `aliás`], [`Speaking of`, `falando em`]],
  focus: `Uma pergunta de continuação vale mais que uma frase perfeita. Quem pergunta mantém a conversa, e a outra pessoa fala mais, então você ouve mais.`,
  tasks: [`Para cada frase, faça 2 perguntas de continuação: “I started a new job.” / “I got a dog.” / “I'm moving.”.`, `Use “By the way” para mudar de assunto numa conversa imaginária.`] },

{ d: 88, title: `A real conversation`, pt: `Uma conversa de verdade`, lvl: 'A2', review: true,
  en: [`Jen: I just got back from a conference in Lisbon.`, `Me: Oh, really? How was it?`, `Jen: Amazing, but exhausting. I gave a presentation in front of two hundred people.`,
       `Me: No way! Were you nervous?`, `Jen: Terrified. But I practiced out loud a lot, and it went well.`,
       `Me: That's huge. I'd be so anxious. Speaking of presentations, I have one next week.`, `Jen: You'll be fine. If I were you, I'd record yourself first.`,
       `Me: That's a good point. By the way, what did you like the most about Lisbon?`, `Jen: The food, for sure. You should definitely go.`],
  tr: [`Jen: Acabei de voltar de uma conferência em Lisboa.`, `Eu: Ah, é? Como foi?`, `Jen: Incrível, mas cansativo. Fiz uma apresentação na frente de duzentas pessoas.`,
       `Eu: Não acredito! Você ficou nervosa?`, `Jen: Apavorada. Mas ensaiei muito em voz alta, e deu certo.`,
       `Eu: Isso é enorme. Eu ficaria muito ansioso. Falando em apresentações, tenho uma semana que vem.`, `Jen: Você vai se sair bem. Se eu fosse você, me gravaria antes.`,
       `Eu: Bom argumento. Aliás, do que você mais gostou em Lisboa?`, `Jen: A comida, com certeza. Você deveria ir sem dúvida.`],
  chunks: [[`I just got back from`, `acabei de voltar de`], [`Oh, really? How was it?`, `ah, é? como foi?`], [`No way!`, `não acredito!`], [`I practiced out loud`, `ensaiei em voz alta`], [`it went well`, `deu certo`], [`Speaking of`, `falando em`], [`You'll be fine`, `você vai se sair bem`], [`By the way`, `aliás`], [`for sure`, `com certeza`]],
  focus: `Revisão: dias 82 a 87. Repare quantas reações e perguntas de continuação cabem numa conversa curta.`,
  tasks: [`Leia os dois papéis e depois faça só o seu, respondendo à Jen do seu jeito.`, `Converse 5 minutos com alguém (Tandem, amigo, colega) usando 3 reações deste mês.`] },

{ d: 89, title: `My English story so far`, pt: `Minha história com o inglês até aqui`, lvl: 'A2',
  en: [`Three months ago, I decided to take English seriously. I had tried before, but I always gave up after a few weeks.`,
       `This time, I did something different. Instead of only studying grammar, I listened and spoke every day. I read one short text a day, repeated it out loud and recorded myself.`,
       `At first, it was frustrating. I couldn't understand much, and I hated my voice in the recordings. But little by little, things started to change.`,
       `Now I can talk about my life, my work and my plans. I still make mistakes, but I'm not afraid of them anymore. And the best part is that I've only just started.`],
  tr: [`Três meses atrás, decidi levar o inglês a sério. Eu já tinha tentado antes, mas sempre desistia depois de algumas semanas.`,
       `Desta vez, fiz algo diferente. Em vez de só estudar gramática, ouvi e falei todos os dias. Li um texto curto por dia, repeti em voz alta e me gravei.`,
       `No começo, foi frustrante. Eu não entendia muito e odiava a minha voz nas gravações. Mas, pouco a pouco, as coisas começaram a mudar.`,
       `Agora consigo falar da minha vida, do meu trabalho e dos meus planos. Ainda cometo erros, mas não tenho mais medo deles. E o melhor é que eu acabei de começar.`],
  chunks: [[`Three months ago`, `três meses atrás`], [`take English seriously`, `levar o inglês a sério`], [`I had tried before`, `eu já tinha tentado antes`], [`I always gave up`, `eu sempre desistia`], [`Instead of`, `em vez de`], [`At first, it was frustrating`, `no começo foi frustrante`], [`things started to change`, `as coisas começaram a mudar`], [`I'm not afraid of them anymore`, `não tenho mais medo deles`], [`I've only just started`, `acabei de começar`]],
  focus: `“Instead of + -ing” = em vez de: Instead of studying only grammar. Depois de preposição, o verbo vai com -ing.`,
  tasks: [`Conte a sua história com o inglês: antes, como foram estes 3 meses e agora.`, `Diga algo que você faz “instead of” outra coisa.`] },

{ d: 90, title: `Phase 1 test`, pt: `Teste da fase 1`, lvl: 'A2',
  en: [`Congratulations! This is the end of phase one. Today's test has three parts. Do them without reading.`,
       `Part one: talk for three minutes about yourself. Your life, your family, your work, your routine and your hobbies.`,
       `Part two: tell a story from your past. Use “When I was a kid, I used to…” and “One day, I was …ing when…”.`,
       `Part three: talk about your future. What are you going to do next year? What would you do if you had more time? Record everything, and listen to it next to your recording from day seven. You'll hear the difference.`],
  tr: [`Parabéns! Este é o fim da fase um. O teste de hoje tem três partes. Faça sem ler.`,
       `Parte um: fale por três minutos sobre você. Sua vida, sua família, seu trabalho, sua rotina e seus hobbies.`,
       `Parte dois: conte uma história do seu passado. Use “When I was a kid, I used to…” e “One day, I was …ing when…”.`,
       `Parte três: fale sobre o seu futuro. O que você vai fazer no ano que vem? O que faria se tivesse mais tempo? Grave tudo e ouça ao lado da sua gravação do dia sete. Você vai ouvir a diferença.`],
  chunks: [[`Congratulations!`, `parabéns!`], [`the end of phase one`, `o fim da fase um`], [`Do them without reading`, `faça sem ler`], [`talk for three minutes about yourself`, `fale três minutos sobre você`], [`tell a story from your past`, `conte uma história do seu passado`], [`What are you going to do next year?`, `o que vai fazer no ano que vem?`], [`What would you do if`, `o que você faria se…?`], [`You'll hear the difference`, `você vai ouvir a diferença`]],
  focus: `Se você conseguiu fazer as três partes, mesmo com erros, a base está pronta. Amanhã começa a fase 2, com missões diárias usando conteúdo real.`,
  tasks: [`Faça as três partes do teste e grave tudo.`, `Compare com o áudio do dia 7. Escreva 3 coisas que melhoraram.`] },
];
